function shell(){return `<header class="topbar"><div class="brand">${btn('mobile-menu','','menu','icon-btn mobile-only','aria-label="打开导航"')}<button class="brand-home" data-action="home" aria-label="返回创作首页"><div class="brand-mark">${icon('film')}</div><div><strong>镜序<span class="brand-dot">.</span></strong><small>AI DIRECTOR STUDIO</small></div></button></div><div class="project-crumb">${btn('home','创作首页','','text-btn studio-location')}${icon('chevron')}<button data-action="projects" class="project-title">${esc(p.title)}${icon('chevron')}</button></div><div class="top-actions">${btn('undo','','undo','icon-btn','title="撤销 (Ctrl+Z)" aria-label="撤销"')}${btn('redo','','redo','icon-btn','title="重做 (Ctrl+Shift+Z)" aria-label="重做"')}<span class="top-divider"></span>${btn('import','导入项目','upload','btn subtle','title="导入 .jingxu.json / .json 项目文件或粘贴 JSON"')}${btn('export','导出项目','download','btn subtle')}${btn('new-project','新建项目','plus','btn primary small')}</div></header>
 <div class="app-shell"><aside class="sidebar"><div class="sidebar-top"><div class="workspace-label">创作空间 <span>WORKSPACE</span></div>${btn('navigate','创作起点','spark',`sidebar-start ${view==='start'?'current':''}`,'data-view="start"')}<div class="mode-switch"><button data-action="mode" data-value="quick" class="${p.mode==='quick'?'active':''}">快速制作</button><button data-action="mode" data-value="director" class="${p.mode==='director'?'active':''}">${icon('camera')}导演模式</button><button data-action="mode" data-value="commerce" class="${p.mode==='commerce'?'active':''}">电商模式</button></div><div class="nav-label">项目创作</div><nav>${[...(p.mode==='commerce'?[['commerce','商品创作台','layers']]:[]),...nav].map(([id,name,ico])=>`<button class="nav-item ${view===id?'active':''}" data-action="navigate" data-view="${id}">${icon(ico)}<span>${name}</span>${['storyboard','characters','scenes'].includes(id)?`<em>${id==='storyboard'?p.shots.length:id==='characters'?p.characters.length:p.scenes.length}</em>`:''}</button>`).join('')}</nav><div class="nav-label resources-label">创作资源</div>${btn('navigate','AI填写','spark',`nav-item ${view==='ai'?'active':''}`,'data-view="ai"')}${btn('blank-project','从零开始','plus','nav-item')}${btn('templates','灵感模板','layers','nav-item')}${btn('preferences','常用与收藏','star','nav-item')}${btn('sources','方法与来源','book','nav-item')}${btn('navigate','服务连接','settings',`nav-item ${view==='connections'?'active':''}`,'data-view="connections"')}</div><div class="sidebar-bottom"><div class="local-label ${saveFailed?'failed':''}"><span class="status-dot"></span><span id="save-label">${saveStatus}</span>${icon('lock')}</div><p>创意留在你的浏览器里。<br>定期导出项目，让灵感有备份。</p><div class="sidebar-footer"><span>镜序工作台</span><span>V1.8</span></div></div></aside><section class="editor-column"><main class="main" id="main"></main><div class="journey-footer" id="journey-footer"></div></section><aside class="preview" id="preview"></aside></div><button class="mobile-preview" data-action="toggle-preview">${icon('eye')}提示词预览<span id="mobile-issue-count"></span></button>`;}
function stats(){return `<div class="project-stats storyboard-top-bar"><div>${icon('clock')}<span><strong data-stat="duration">${M.fmt(M.totalDuration(p))}</strong> / ${p.targetDuration} 秒</span></div><div>${icon('board')}<span><strong data-stat="shots">${p.shots.length}</strong> 镜</span></div><div>${icon('scene')}<span>${p.format}</span></div><div><span class="tiny-badge">${p.resolution}</span><span>${p.fps}fps</span></div><label class="chain-inline-toggle" title="勾选后在提示词中加入5条逐镜生成+上镜尾帧作下镜输入图+逐秒抽帧检查铁律，并与 AI 填写同步"><input type="checkbox" data-bind="chainLastFrame" ${p.chainLastFrame?'checked':''}><span>尾帧接下一镜首帧</span></label><label class="chain-inline-toggle cut-check-pill ${p.cutFrameCheck?'active':''}" title="勾选后在生成阶段严格检查上一镜尾帧与下一镜首帧一致性（头发/手臂/衣服/位置不跳变）；后期转场仍按剪辑执行表无条件执行"><input type="checkbox" data-bind="cutFrameCheck" ${p.cutFrameCheck?'checked':''}><span>切点前后两帧检查</span></label><div class="stats-spacer"></div>${btn('auto-enrich-all','⚡ 全片一键细化','spark','btn subtle small','title="自动补全所有镜头的导演意图、空间视线、逐秒时间轴与声音排雷"')}<div class="layout-switch" role="group" aria-label="分镜浏览模式"><button type="button" data-action="storyboard-layout" data-value="tabs" class="${storyboardMode==='tabs'?'active':''}" title="像浏览器标签页一样单镜切换，无需上下滚动">单镜页签</button><button type="button" data-action="storyboard-layout" data-value="list" class="${storyboardMode==='list'?'active':''}" title="纵向展开全部镜头列表">全部列表</button></div>${btn('specs','项目设置','settings','text-btn')}</div>`;}
function shortTransName(id){const l=M.label(p,'transition',id||'cut');return l.replace(/[（(][^）)]*[）)]/g,'').trim()||'硬切';}
function timelineView(){const times=M.timeline(p),total=Math.max(1,M.totalDuration(p));return `<section class="timeline-panel browser-tabs-panel"><div class="timeline-title"><span>${icon('layers')}分镜页签 / 故事时间轴 <small>点击页签切镜 · 点击镜头间 ⇄ 胶囊设置场景/镜头转场 · 共 ${M.fmt(total)}s</small></span><div class="timeline-quick-tools">${p.shots.length>1?`${btn('prev-shot','上一镜','','text-btn',selected<=0?'disabled':'')}<span class="shot-pos-indicator">${selected+1} / ${p.shots.length}</span>${btn('next-shot','下一镜','','text-btn',selected>=p.shots.length-1?'disabled':'')}`:''}</div></div><div class="timeline-track browser-tab-track" role="tablist" aria-label="分镜浏览器页签">${times.map((t,i)=>{const s=p.shots[i],next=p.shots[i+1],isSceneChange=Boolean(next&&s.sceneId&&next.sceneId&&s.sceneId!==next.sceneId);const bridge=next?`<button type="button" class="tab-transition-bridge ${isSceneChange?'cross-scene':''}" data-action="open-transition-modal" data-index="${i}" title="${isSceneChange?'跨场景过渡（场景A→场景B）· ':''}配置第 ${i+1} 镜 → 第 ${i+2} 镜转场：${esc(M.label(p,'transition',s.transition||'cut'))}"><span>${isSceneChange?'⚡ 跨场 · ':''}${esc(shortTransName(s.transition||'cut'))}</span></button>`:'';return `<button type="button" role="tab" aria-selected="${i===selected}" class="timeline-segment browser-shot-tab ${i===selected?'active':''}" data-action="select-shot" data-index="${i}" style="--grow:${Math.max(.1,t.duration)}"><span class="tab-num">${String(i+1).padStart(2,'0')}</span><b>${esc(s.title||'未命名镜头')}</b><small>${M.fmt(t.start)}–${M.fmt(t.end)}s</small></button>${bridge}`;}).join('')}<button type="button" class="browser-tab-add" data-action="add-shot" title="添加新镜头" aria-label="添加新镜头">${icon('plus')}<span>新镜头</span></button></div></section>`;}
function storyboard(){const cur=p.shots[selected];return heading('STORYBOARD / 分镜创作','每一秒，都有叙事。','点击上方分镜页签即可像浏览器切换网页一样直达对应分镜，点击镜头间转场胶囊可调节6大类108种场景转场。','')+stats()+timelineView()+(storyboardMode==='list'?`<div class="section-toolbar"><h2>镜头列表 <span>${String(p.shots.length).padStart(2,'0')}</span></h2><div><span class="muted desktop-label">${icon('grip')}拖动调整顺序</span>${btn('add-shot','添加镜头','plus','btn primary small')}</div></div>`:'')+`<div class="shot-list ${storyboardMode==='tabs'?'shot-list-tabs':'shot-list-all'}">${!p.shots.length?`<div class="empty-state">${icon('board')}<h3>从第一个镜头开始</h3><p>选择人物与场景，写下这一刻发生什么。</p>${btn('add-shot','添加第一个镜头','plus','btn primary')}</div>`:storyboardMode==='tabs'?shotCard(cur||p.shots[0],cur?selected:0,true):p.shots.map((s,i)=>shotCard(s,i,false)).join('')}</div>${storyboardMode==='list'&&p.shots.length?btn('add-shot','继续添加镜头','plus','add-shot-wide'):''}`;}
function shotCard(s,i,forceOpen=false){const t=M.timeline(p)[i]||{start:0,end:M.n(s.duration),duration:M.n(s.duration)},sc=p.scenes.find(x=>x.id===s.sceneId),sp=p.characters.find(x=>x.id===s.speakerId),active=forceOpen||storyboardMode==='tabs'||expandedShots.has(s.id),issues=M.checkProject(p).filter(x=>x.index===i&&x.severity!=='info'),c=M.camera(p,s);return `<article class="shot-card ${active?'active':''} ${storyboardMode==='tabs'?'tab-active-card':''}" data-shot-index="${i}" id="shot-${i}"><div class="shot-head"><button class="drag-handle" draggable="true" data-index="${i}" title="拖动镜头 ${i+1}" aria-label="拖动镜头 ${i+1}">${icon('grip')}</button><button class="shot-select" data-action="select-shot" data-index="${i}" aria-expanded="${active}"><span class="shot-number">${String(i+1).padStart(2,'0')}</span><div><strong>${esc(s.title)}</strong><div class="shot-subtitle"><span>${M.fmt(t.start)}–${M.fmt(t.end)}s</span><span>·</span><span>${esc(sc?.name||'待选场景')}</span><span>·</span><span>${esc(M.label(p,'framing',c.framing))} / ${esc(M.label(p,'move',c.move))}</span>${s.segments?.length?`<span>· ${s.segments.length}段时序</span>`:''}${s.transition?`<span>· ${esc(M.label(p,'transition',s.transition))}</span>`:''}${issues.length?`<span class="issue-dot">${issues.length} 项待检查</span>`:''}</div></div></button><div class="shot-head-actions">${btn('auto-enrich-shot','⚡ 补全本镜','spark','btn subtle small',`data-index="${i}" title="一键补全本镜的导演意图、空间视线、逐秒时间轴与声音排雷"`)}${btn('edit-speech','表演与声音','sound','btn subtle small',`data-index="${i}"`)}<span class="duration-badge">${M.fmt(s.duration)}s</span>${btn('copy-shot','','copy','icon-btn',`data-index="${i}" title="复制本镜提示词" aria-label="复制镜头 ${i+1} 提示词"`)}${btn('duplicate-shot','','layers','icon-btn',`data-index="${i}" title="复制镜头" aria-label="复制镜头 ${i+1}"`)}${btn('shot-menu','','settings','icon-btn',`data-index="${i}" title="镜头操作（移动/拆分/合并/删除）" aria-label="镜头 ${i+1} 操作"`)}${storyboardMode==='list'?`<button data-action="select-shot" data-index="${i}" class="icon-btn expand-shot ${active?'expanded':''}" aria-label="${active?'收起':'展开'}镜头 ${i+1}" aria-expanded="${active}">${icon('chevron')}</button>`:''}</div></div>${active?shotEditor(s,i):`<div class="shot-summary"><span>${icon('camera')}${esc(M.label(p,'framing',c.framing))} · ${esc(M.label(p,'move',c.move))}${c.moveDistance&&c.moveDistance!=='none'?'（'+esc(M.label(p,'moveDistance',c.moveDistance))+'）':''}</span><p>${esc(s.action||'点击镜头填写内容')}</p>${s.dialogue?`<div class="shot-summary-dialogue">${icon('sound')}<strong>${esc(sp?.name||'对白')}：</strong><span>“${esc(s.dialogue)}”</span></div>`:''}</div>`}</article>`;}
function shotEditor(s,i){s.acting??={};s.continuitySpec??={};s.soundCues??=[];s.transitionSpec??=M.transitionSpecDefaults();const base=`shots.${i}`,c=M.camera(p,s),next=p.shots[i+1],scA=p.scenes.find(x=>x.id===s.sceneId),scB=next?p.scenes.find(x=>x.id===next.sceneId):null,isSceneChange=Boolean(scA&&scB&&scA.id!==scB.id);return `<div class="shot-body compact-shot-body"><div class="shot-meta-row"><div class="grid cols-title">${input(`${base}.title`,'镜头名称')}${input(`${base}.duration`,'时长 / 秒',{type:'number',min:.1,step:.5})}${p.timing==='free'?input(`${base}.manualStart`,'起点 / 秒',{type:'number',min:0,step:.5}):''}${select(`${base}.sceneId`,'所在场景',p.scenes.map(x=>[x.id,x.name]))}</div><div class="shot-assets"><label>出场人物 <small class="muted">未勾选角色将在提示词中标明本镜不出场</small></label><div class="inline-choices">${p.characters.map((ch,k)=>`<button data-action="shot-character" data-index="${i}" data-id="${ch.id}" class="actor-chip ${s.characterIds.includes(ch.id)?'active':''}"><span class="avatar tiny a${k%4}">${esc(ch.name.slice(-1))}</span>${esc(ch.name)}${s.characterIds.includes(ch.id)?icon('check'):''}</button>`).join('')}${p.characters.length?btn('navigate','管理人物','plus','text-btn','data-view="characters"'):btn('related-asset','去添加人物','plus','text-btn',`data-path="shots.${i}.characterIds"`)}</div></div></div><div class="shot-grid-two"><div class="shot-col-main shot-subcard"><label class="field action-field"><span>这一镜，发生什么？ <small>核心可见动作与起因结果</small></span><textarea aria-label="这一镜发生什么" data-bind="${base}.action" class="action-input" rows="2" placeholder="例如：听见画外的呼唤，她停顿片刻，缓缓回头……">${esc(s.action)}</textarea></label><div class="quick-actions"><span>快捷</span>${ACTIONS.slice(0,p.mode==='quick'?3:5).map(x=>btn('append-action',x,'','quick-chip',`data-index="${i}" data-value="${x}"`)).join('')}${btn('auto-segments','⚡ 按秒拆解','spark','quick-chip accent-chip',`data-index="${i}"`)}${btn('auto-enrich-shot','⚡ 智能补全','spark','quick-chip accent-chip',`data-index="${i}"`)}</div></div><div class="shot-col-dialogue inline-dialogue-box shot-subcard"><label class="field"><span>本镜对白与声音 <small>留空则无对白 · 自动同步口型时间窗</small></span><textarea aria-label="本镜对白" data-bind="${base}.dialogue" rows="2" placeholder="输入角色台词；不填则为纯画面镜头">${esc(s.dialogue)}</textarea></label><div class="grid two compact-subgrid">${select(`${base}.speakerId`,'说话者',p.characters.map(x=>[x.id,x.name]))}${input(`${base}.delivery`,'语气 / 停顿',{placeholder:'平静 / 低声 / 急促'})}${input(`${base}.audio`,'动作音效 / 画外音',{placeholder:'杯碟轻响 / 破窗声'})}${dataliChoice(`${base}.music`,`shot-music-list-${i}`,'本镜配乐 / BGM',['无背景音乐','本镜暂停配乐（静默）',...GROUPS.bgm.options.filter(x=>x.id!=='none').map(x=>x.label+' · 轻柔铺底')],'留空默认继承全局BGM')}</div></div></div><div class="shot-grid-two"><div class="shot-subcard">${input(`${base}.intent`,'导演意图 · 为什么这样拍',{area:true,placeholder:'例如：用固定中景表现独处平静，再缓推放大眼神警觉。'})}</div><div class="shot-subcard">${input(`${base}.spatial`,'空间位置与视线关系',{area:true,placeholder:'例如：竖屏构图，林夏坐窗边右侧，入口在左前方，视线看向入口不看镜头。'})}</div></div><div class="shot-grid-two"><div class="shot-camera-row shot-subcard"><div class="state-line">${icon('camera')}<span>摄影与运镜</span><small>物理位移严禁混用变焦</small>${btn('shot-camera','细调运镜','settings','btn subtle small',`data-index="${i}"`)}</div><div class="camera-mini-summary"><strong>${M.label(p,'framing',c.framing)} <span>·</span> ${M.label(p,'move',c.move)}${c.moveDistance&&c.move!=='fixed'?' · '+M.label(p,'moveDistance',c.moveDistance):''}</strong></div>${cameraPresetSelector(s,i)}</div><div class="end-state shot-subcard"><div class="state-line">${icon('arrow')}<span>收尾状态与场景/镜头转场</span><small>${isSceneChange?`⚡ 跨场景：${esc(scA.name)} → ${esc(scB.name)}`:'决定本镜落幅与下一镜过渡方式'}</small>${next?btn('open-transition-modal','🎬 108种转场 / 十项规范','layers','btn subtle small',`data-index="${i}"`):''}</div><textarea aria-label="收尾状态" data-bind="${base}.endState" rows="2" placeholder="镜头结束时人在哪里、看向哪里、定格姿态？">${esc(s.endState)}</textarea><div class="end-trans-row">${picker('transition',`${base}.transition`,{compact:true})}${next?btn('auto-transition-spec','⚡ 智能配转场','spark','btn subtle small',`data-index="${i}" title="结合前后两镜场景/运镜自动挑选转场并生成十项AI转场规范"`):''}</div></div></div>${segmentEditor(s,i)}${disclosure('shot-'+s.id,s.dialogue?'展开：模块B连续性锁、负面排雷与对白时间窗 · 含对白':'展开：模块B连续性锁、起始状态与场景化负面排雷',directorFields(s,i))}<div class="shot-bottom"><span>${icon('check')}提示词实时同步右侧预览</span><div>${btn('edit-speech','微表演与声音时间轴','sound','text-btn',`data-index="${i}"`)}${btn('copy-frame','首帧提示词','scene','text-btn',`data-index="${i}" data-frame="first"`)}${btn('copy-frame','尾帧提示词','scene','text-btn',`data-index="${i}" data-frame="last"`)}</div></div></div>`;}
function directorFields(s,i){const b=`shots.${i}`;return `<div class="director-fields"><div class="subsection-title">${icon('camera')}导演调度与连续性模块 <span>DIRECTOR NOTES & CONTINUITY</span></div><div class="grid two">${select(`${b}.purpose`,'镜头职责',PURPOSES)}${select(`${b}.emotion`,'情绪基调',GROUPS.emotion.options.map(x=>[x.id,x.label]))}</div><div class="generation-fields"><div class="grid three">${input(`${b}.generationDuration`,'计划生成素材 / 秒',{type:'number',min:.1,step:.5})}${input(`${b}.trimIn`,'剪辑入点 / 秒',{type:'number',min:0,step:.1})}${input(`${b}.trimOut`,'剪辑出点 / 秒',{type:'number',min:0,step:.1})}</div></div>${toggle(`${b}.inheritStart`,'继承上一镜的结束状态',i===0?'第一镜仍需填写起点':'同场景、连续时空中生效')}${input(`${b}.startState`,'起始状态',{area:true,disabled:s.inheritStart&&i>0,hint:s.inheritStart&&i>0?`当前继承：${esc(M.startState(p,i)||'上一镜终点尚未填写')}`:'只描述动作发生前这一瞬间。'})}<div class="grid two">${select(`${b}.continuity`,'与上一镜关系',[['continuous','连续时空'],['timejump','时间省略 / 跳跃'],['replay','有意回放'],['newscene','独立起点']])}${select(`${b}.propId`,'追踪道具',[['','不追踪'],...p.props.map(x=>[x.id,x.name])])}</div>${s.propId?`<div class="grid two">${select(`${b}.handStart`,'起点持物位置',Object.entries({unknown:'未知',right:'右手',left:'左手',both:'双手',table:'桌面 / 场景中',none:'未持有'}),{hint:s.inheritStart&&i>0?'继承生效时以继承结果为准。':''})}${select(`${b}.handEnd`,'终点持物位置',Object.entries({unknown:'未知',right:'右手',left:'左手',both:'双手',table:'桌面 / 场景中',none:'未持有'}))}${input(`${b}.propStart`,'道具起点状态',{placeholder:'折叠、闭合、干燥…'})}${input(`${b}.propEnd`,'道具终点状态',{placeholder:'展开、打开、湿润…'})}</div>`:''}<div class="continuity-box"><div class="picker-title"><label>模块B：本镜连续性约束锁定 <span class="muted">留空时自动汇总角色/道具/场景设定</span></label></div><div class="grid two">${input(`${b}.continuitySpec.character`,'人物连续性',{placeholder:'面部、年龄、发型、服装一致'})}${input(`${b}.continuitySpec.prop`,'道具连续性',{placeholder:'始终由右手持有，不得消失或换手'})}${input(`${b}.continuitySpec.space`,'空间连续性',{placeholder:'桌椅、台灯、窗户方位不变'})}${input(`${b}.continuitySpec.lighting`,'光影连续性',{placeholder:'台灯暖光在左前侧，窗外冷蓝雨夜'})}</div>${input(`${b}.continuitySpec.action`,'动作与首尾衔接约束',{placeholder:'下一镜头从本镜结束时的姿态开始'})}</div><div class="shot-negative-box"><div class="picker-title"><label>本镜场景化负面排雷 <span class="muted">针对具体手部、道具与运镜风险</span></label>${btn('suggest-shot-negatives','⚡ 生成本镜排雷词','spark','text-btn',`data-index="${i}"`)}</div>${input(`${b}.negativeNotes`,'禁止出现的风险（进入负面提示词）',{area:true,placeholder:'例如：禁止信纸左右手互换或变形、禁止未授权切镜、禁止面部过度磨皮、禁止口型错位…'})}</div>${s.dialogue?`<div class="grid three">${input(`${b}.dialogueLanguage`,'台词语言')}${input(`${b}.dialogueStart`,'对白开始 / 秒',{type:'number',min:0,step:.1})}${input(`${b}.dialogueEnd`,'对白结束 / 秒',{type:'number',min:0,step:.1})}</div>`:''}<div class="director-speech-jump">${btn('edit-speech',s.dialogue?'在「表演与声音」细调六部位微表演与声音时间轴':'去「表演与声音」设置六部位微表演与声音时间轴','sound','btn subtle small',`data-index="${i}"`)}</div>${input(`${b}.notes`,'创作备注（不进入提示词）',{area:true})}</div>`;}
function segmentEditor(s,i){return `<section class="segments compact-segments"><div class="picker-title"><label>模块A：镜内动作时间轴 <span class="muted">${s.segments.length?`已拆解 ${s.segments.length} 段逐秒动作（含段间转场可选）`:'未拆解时可点击右侧按秒生成'}</span></label><div class="seg-actions">${btn('auto-segments','⚡ 按秒拆解','spark','text-btn',`data-index="${i}"`)}${btn('add-segment','添加分段','plus','text-btn',`data-index="${i}"`)}</div></div>${s.segments.length?`<div class="segment-table">${s.segments.map((seg,j)=>`<div class="segment-row compact-segment-row"><div class="segment-times">${input(`shots.${i}.segments.${j}.start`,'起(s)',{type:'number',min:0,step:.5})}<span>–</span>${input(`shots.${i}.segments.${j}.end`,'止(s)',{type:'number',min:0,step:.5})}</div><div class="segment-cells">${input(`shots.${i}.segments.${j}.action`,'可见动作',{placeholder:'这一秒发生了什么动作'})}${input(`shots.${i}.segments.${j}.performance`,'微表演/眼神',{placeholder:'眼球转动/神态变化'})}${input(`shots.${i}.segments.${j}.cameraBeat`,'机位/焦点',{placeholder:'缓推/焦点锁定'})}${input(`shots.${i}.segments.${j}.audio`,'声音/对白同步',{placeholder:'环境音/音效/台词同步'})}<label class="field seg-trans-field"><span>段尾转场</span><select aria-label="第${j+1}段段尾转场" data-bind="shots.${i}.segments.${j}.transition">${groupedTransitionOptions(seg.transition||'',null,'无 / 自然顺接')}</select></label></div>${btn('delete-segment','','trash','icon-btn',`data-index="${i}" data-segment="${j}" aria-label="删除时间段 ${j+1}"`)}</div>`).join('')}</div>`:hint('点击“⚡ 按秒拆解”可一键把当前镜头拆分成 0–1s、1–3s 等逐秒动作节拍，每段末尾还支持选择动作内转场。')}</section>`;}
function styleView(){return heading('LOOK DEVELOPMENT / 影像设定','给故事，一种质感。','风格描述画面如何呈现；分辨率与帧率在项目规格中独立设置。',btn('preferences','常用排序','star','btn subtle'))+`<div class="look-overview"><div class="look-art">${art(p.theme)}<span>氛围构图示意 · 非生成结果</span></div><div><span class="eyebrow">YOUR VISUAL DIRECTION</span><h2>${esc(M.label(p,'look',p.style.look))}</h2><p>${esc(M.label(p,'medium',p.style.medium))} / ${esc(M.label(p,'color',p.style.color))}</p><div class="look-tags">${p.style.texture.map(x=>`<span>${esc(M.label(p,'texture',x))}</span>`).join('')}</div></div></div>`+panel('画面风格',['look','medium','genre','color','texture'].map(key=>picker(key,`style.${key}`)).join(''),'选中后可在右侧看到对应的自然语言。')+panel('补充你的视觉描述',input('style.custom','自定义质感',{area:true,placeholder:'例如：雨滴在镜片边缘形成轻微折射，保留真实的衣料褶皱……'})+hint('品牌名称用于风格参考，实际表现由具体画面描述和生成平台共同决定。'));}
function charactersView(){const c=p.characters[castSelected];return heading('CAST & CONTINUITY / 角色资产','让每一次出场，都是同一个人。','身份、造型和当镜状态分别管理。锁定字段可先解锁再修改。',btn('add-character','添加角色','plus','btn primary'))+`<div class="asset-tabs">${p.characters.map((c,i)=>`<button data-action="select-character" data-index="${i}" class="asset-tab ${castSelected===i?'active':''}"><span class="avatar a${i%4}">${esc(c.name.slice(-1)||'?')}</span><span><strong>${esc(c.name)}</strong><small>${esc(c.variant)}</small></span></button>`).join('')}<button type="button" data-action="add-character" class="asset-tab asset-tab-add">${icon('plus')}<span>添加角色</span></button></div>`+(c?characterEditor(c,castSelected):hint('添加第一个角色。'))+propEditor();}
function characterEditor(c,i){const b=`characters.${i}`,appearance=['age','gender','height','build','appearance','skin','face','eyes','brows','nose','lips'],hair=['hair','hairColor'],outfit=['outfit','accessories'],voice=['voice','language'];const lockFor=k=>appearance.includes(k)?'appearance':hair.includes(k)?'hair':outfit.includes(k)?'outfit':voice.includes(k)?'voice':null;const sets={basic:['name','age','gender','height','build','occupation','appearance','variant'],face:['skin','face','eyes','brows','nose','lips'],look:['hair','hairColor','makeup','outfit','accessories'],voice:['habits','voice','language'],all:CHARACTER_FIELDS.map(([k])=>k)};const visible=CHARACTER_FIELDS.filter(([k])=>(sets[characterGroup]||sets.basic).includes(k));return panel('角色档案',`<div class="character-groups">${[['basic','基础属性'],['face','五官肤质'],['look','发型服装'],['voice','姿态声音'],['all','全部展开']].map(([k,l])=>btn('character-group',l,'',`tag-button ${characterGroup===k?'selected':''}`,`data-value="${k}"`)).join('')}</div><div class="face-presets"><span>五官快捷组合</span><select aria-label="五官快捷组合" data-ui="preset-faces"><option value="">选择五官组合（${ALL_FACES.length}套）</option>${ALL_FACES.map((x,k)=>`<option value="${k}">${esc(x.name)}</option>`).join('')}</select><small>先预览，再填入；已锁定字段会跳过。</small></div><div class="lock-grid">${[['appearance','外貌'],['hair','发型'],['outfit','服装'],['voice','声音']].map(([k,l])=>btn('lock',`${c.locks[k]?'已锁定':'锁定'}${l}`,c.locks[k]?'lock':'unlock',`lock-button ${c.locks[k]?'locked':''}`,`data-index="${i}" data-key="${k}"`)).join('')}</div><div class="grid two character-fields char-group-${characterGroup}">${visible.map(([k,l])=>attributeField(`${b}.${k}`,k,l,!!c.locks[lockFor(k)])).join('')}</div>${p.mode==='quick'?btn('mode','展开五官、体态与习惯','settings','btn subtle','data-value="director"'):''}<div class="panel-footer">${btn('save-character-template','保存角色模板','star','btn subtle',`data-index="${i}"`)}${btn('duplicate-character','另存造型版本','copy','text-btn',`data-index="${i}"`)}${btn('delete-character','删除角色','trash','text-btn danger',`data-index="${i}"`)}</div>`,'锁定保护当前造型；另存版本可保留身份描述再修改衣着。');}
function propEditor(){return panel('关键道具',`<div class="prop-list">${p.props.map((x,i)=>`<div class="prop-row"><span class="prop-icon">${icon('layers')}</span><div>${input(`props.${i}.name`,'名称')}${input(`props.${i}.appearance`,'外观与材质')}</div>${btn('delete-prop','','trash','icon-btn',`data-index="${i}" aria-label="删除道具 ${esc(x.name)}"`)}</div>`).join('')}</div>${btn('add-prop','添加关键道具','plus','btn subtle')}`,'持物手与道具开合等变化，记录在具体镜头。');}
function scenesView(){const s=p.scenes[sceneSelected],i=sceneSelected;return heading('WORLD & LIGHT / 场景资产','先有空间，再有光。','设置地点、环境动态与有出处的光线，让跨镜保持同一空间。',btn('add-scene','添加场景','plus','btn primary'))+`<div class="asset-tabs">${p.scenes.map((s,i)=>`<button data-action="select-scene" data-index="${i}" class="asset-tab ${sceneSelected===i?'active':''}"><span class="scene-tab-icon">${icon('scene')}</span><span><strong>${esc(s.name)}</strong><small>${M.label(p,'time',s.time)} · ${M.label(p,'weather',s.weather)}</small></span></button>`).join('')}<button type="button" data-action="add-scene" class="asset-tab asset-tab-add">${icon('plus')}<span>添加场景</span></button></div>`+(s?panel('场景设定',`<div class="grid two scene-fields">${SCENE_FIELDS.map(([k,l])=>input(`scenes.${i}.${k}`,l)).join('')}</div>${picker('time',`scenes.${i}.time`)}${picker('weather',`scenes.${i}.weather`)}<div class="panel-footer">${btn('delete-scene','删除场景','trash','text-btn danger',`data-index="${i}"`)}</div>`)+panel('有动机的光影',picker('lightSource',`scenes.${i}.lightSource`)+picker('lightDirection',`scenes.${i}.lightDirection`)+picker('lightQuality',`scenes.${i}.lightQuality`)+input(`scenes.${i}.lightNote`,'光线落在什么地方',{area:true,placeholder:'例如：逆光勾勒发丝，环境补光保留面部层次，暖光映在湿润栏杆上。'}),'光源 → 方向与质地 → 材质反馈 → 色彩关系。')+(p.mode==='director'?layoutEditor(s,i):hint('导演模式可展开人物、摄影机与主光的二维布局。')):'');}
function layoutEditor(s,i){const l=s.layout;return panel('空间与轴线示意',`<div class="spatial-diagram"><svg viewBox="0 0 100 100" role="img" aria-label="人物与摄影机空间示意"><defs><pattern id="grid" width="10" height="10" patternUnits="userSpaceOnUse"><path d="M10 0H0V10" fill="none" stroke="#ffffff0c" stroke-width=".3"/></pattern></defs><rect width="100" height="100" fill="url(#grid)"/><path d="M${l.ax} ${l.ay}L${l.bx} ${l.by}" stroke="#daa57a" stroke-width=".5" stroke-dasharray="2 2"/><path d="M${l.cx} ${l.cy} Q15 45 ${l.ax} ${l.ay}" stroke="#79a49e" stroke-width=".6" fill="none" stroke-dasharray="2 2"/><path d="M${l.cx} ${l.cy}L${l.ax-12} ${l.ay}L${l.ax+12} ${l.ay}Z" fill="#79a49e0c" stroke="#79a49e44" stroke-width=".4"/><circle cx="${l.ax}" cy="${l.ay}" r="4" fill="#ecab7c"/><text x="${l.ax}" y="${l.ay+1.3}" text-anchor="middle">A</text><circle cx="${l.bx}" cy="${l.by}" r="4" fill="#95b7af"/><text x="${l.bx}" y="${l.by+1.3}" text-anchor="middle">B</text><rect x="${l.cx-4}" y="${l.cy-3}" width="8" height="6" rx="1" fill="#8da9be"/><text x="${l.cx}" y="${l.cy+1.2}" text-anchor="middle">机</text><circle cx="${l.lx}" cy="${l.ly}" r="3" fill="#dfc481"/><text x="${l.lx}" y="${l.ly-5}" text-anchor="middle" fill="#dfc481">主光</text></svg><div class="diagram-legend"><span>● 人物</span><span>▰ 摄影机</span><span>┄ 对话轴线</span></div></div><div class="grid four">${[['ax','A 横向'],['ay','A 纵向'],['bx','B 横向'],['by','B 纵向'],['cx','摄影机横向'],['cy','摄影机纵向'],['lx','光源横向'],['ly','光源纵向']].map(([k,l])=>input(`scenes.${i}.layout.${k}`,l,{type:'number',min:0,step:1})).join('')}</div>${hint('这是可调整的二维规划示意，不是精确三维模拟；A/B代表空间位置，具体出场角色以分镜选择为准。')}`);}
function motionDiagram(c){const orbit=c.move==='orbit',fixed=c.move==='fixed';return `<div class="motion-demo"><svg viewBox="0 0 320 150" aria-label="${esc(M.label(p,'move',c.move))}运动示意" role="img"><defs><marker id="motionArrow" markerWidth="5" markerHeight="5" refX="4" refY="2.5" orient="auto-start-reverse"><path d="m0 0 5 2.5L0 5Z" fill="#e9ac80"/></marker></defs><ellipse cx="160" cy="74" rx="88" ry="44" fill="none" stroke="#ffffff0f" stroke-dasharray="4 4"/><path d="M20 118h280M160 18v115" stroke="#ffffff08"/><circle cx="160" cy="74" r="13" fill="#92b0a322" stroke="#92b0a3"/><text x="160" y="78" text-anchor="middle" fill="#b7c8be" font-size="11">主体</text>${orbit?`<path d="${c.direction==='cw'?'M72 76C72 18 249 18 249 76':'M249 76C249 18 72 18 72 76'}" stroke="#e9ac80" stroke-width="2" fill="none" marker-end="url(#motionArrow)"/><text x="160" y="18" fill="#e9ac80" text-anchor="middle" font-size="11">${c.orbit}° ${c.direction==='cw'?'顺时针':'逆时针'}</text>`:fixed?'<rect x="150" y="117" width="20" height="13" rx="3" fill="#e9ac80"/>':`<path d="${c.move==='track'?'M76 116H244':c.move==='pull'?'M160 96V136':'M160 136V96'}" stroke="#e9ac80" stroke-width="2" marker-end="url(#motionArrow)"/><rect x="${c.move==='track'?70:151}" y="120" width="18" height="12" rx="3" fill="#e9ac80"/>`}</svg><div><strong>${M.label(p,'move',c.move)}</strong><p>参数示意 · 非生成视频</p></div></div>`;}
function webTabBar(action,active,tabs,trailing=''){return `<div class="timeline-track browser-tab-track web-tab-track" role="tablist">${tabs.map(([id,num,title,sub])=>`<button type="button" role="tab" aria-selected="${String(active)===String(id)}" data-action="${action}" data-value="${esc(id)}" class="browser-shot-tab web-tab ${String(active)===String(id)?'active':''}"><span class="tab-num">${esc(num)}</span><span class="web-tab-text"><b>${esc(title)}</b>${sub!==undefined?`<small data-tab-meta="${action}:${esc(id)}">${esc(sub)}</small>`:''}</span></button>`).join('')}${trailing}</div>`;}
function cameraView(){p.cameraDraft??=M.clone(p.camera);const d=p.cameraDraft,cTabs=[['composition','01','镜头与构图',`${M.label(p,'framing',d.framing)}·${M.label(p,'lens',d.lens)}`],['motion','02','摄影机运动',`${M.label(p,'move',d.move)}${d.lockFrame?'·锁定':''}`],['focus','03','对焦与景深',M.label(p,'focus',d.focus)],...(p.mode==='director'?[['optics','04','旋转与光学',`${M.label(p,'rotation',d.rotation)}·${M.label(p,'zoom',d.zoom)}`]]:[])];if(!cTabs.some(x=>x[0]===cameraTab))cameraTab='composition';const compBody=['framing','angle','composition','lens'].map(k=>picker(k,`cameraDraft.${k}`)).join('');const motionBody=picker('move','cameraDraft.move')+picker('moveDistance','cameraDraft.moveDistance')+picker('speed','cameraDraft.speed')+(d.move==='orbit'?`<div class="grid two">${select('cameraDraft.direction','俯视方向',[['cw','顺时针'],['ccw','逆时针']])}${select('cameraDraft.orbit','环绕角度',[[45,'45°'],[90,'90°'],[180,'180°'],[270,'270°'],[360,'360°']])}</div>${toggle('cameraDraft.subjectTurn','人物随镜头转身')}`:'')+`<div class="grid two">${input('cameraDraft.start','摄影机起始位置',{placeholder:'人物正前方 / 画面左侧…'})}${input('cameraDraft.end','摄影机结束状态',{placeholder:'沿光轴轻微推进至面部占画面主要区域…'})}</div>`+picker('stability','cameraDraft.stability')+input('cameraDraft.hold','结束停留 / 秒',{type:'number',min:0,step:.1})+toggle('cameraDraft.lockFrame','完全锁定画面','开启后，摄影机不位移、不旋转。');const focusBody=picker('focus','cameraDraft.focus')+(d.focus==='rack'?`<div class="grid two">${input('cameraDraft.focusFrom','起始焦点 A')}${input('cameraDraft.focusTo','结束焦点 B')}</div>`:'');const opticsBody=p.mode==='director'?picker('rotation','cameraDraft.rotation')+picker('zoom','cameraDraft.zoom')+hint('物理位移与光学变焦不同；推进/后拉时建议将光学变焦保持“不变焦”。'):'';const bodyMap={composition:compBody,motion:motionBody,focus:focusBody,optics:opticsBody};return heading('CAMERA LANGUAGE / 摄影调度','把摄影设计，存成预选。','点击上方页签切换「镜头构图 / 机位运动 / 对焦景深」，编辑并保存一套摄影设置。',btn('apply-global-camera','应用到全部镜头','check','btn subtle'))+cameraLibraryPanel()+motionDiagram(d)+`<section class="web-tabs-shell">${webTabBar('camera-tab',cameraTab,cTabs)}<div class="web-tab-panel">${bodyMap[cameraTab]||compBody}</div></section>`;}
function performanceView(){p.bgm??=M.bgmDefaults();const s=p.shots[selected];if(s){s.acting??={};s.soundCues??=[];}const bgmSub=p.bgm.style?(p.bgm.style==='none'?'无配乐':M.label(p,'bgm',p.bgm.style).split(' / ')[0]):'未设置';const soundCount=(s?.soundCues?.length||0)+(s?.dialogue?1:0);const pTabs=[['acting','01','细腻微表演',s?M.label(p,'emotion',s.emotion):'未选镜头'],['sound','02','对白与声音',s?(s.dialogue?`有对白·${soundCount}项`:`${s.soundCues.length}条线索`):'待添镜头'],['bgm','03','全局 BGM 配乐',bgmSub],['segments','04','镜内动作时序',s?`${s.segments.length}段时序`:'0段']];const actingBody=s?`<div class="panel-heading"><div><h3>细腻表演与分部位指导</h3><p>控制每个部位的具体反应顺序，决定画面是否像真人表演。</p></div></div>`+picker('emotion',`shots.${selected}.emotion`)+select(`shots.${selected}.intensity`,'表演强度',['克制','自然','外放'])+picker('micro',`shots.${selected}.micro`)+`<div class="acting-details-box"><div class="picker-title"><label>演员动作微控制（避免AI机械表演） <span class="muted">眼神 / 眉毛 / 嘴唇 / 呼吸 / 头部 / 肩背</span></label></div><div class="acting-combos"><span>一键填入：</span>${ACTING_COMBOS.map((x,k)=>btn('apply-acting-combo',x.name,'','quick-chip',`data-index="${selected}" data-value="${k}"`)).join('')}</div><div class="grid two">${input(`shots.${selected}.acting.eyes`,'眼神变化与转动顺序',{placeholder:'先平静，眼球先转向声源再抬眼'})}${input(`shots.${selected}.acting.brows`,'眉毛微动',{placeholder:'轻微收紧呈警觉感'})}${input(`shots.${selected}.acting.lips`,'嘴唇与下颌',{placeholder:'保持自然闭合不僵硬'})}${input(`shots.${selected}.acting.breathing`,'呼吸节奏',{placeholder:'听声瞬间短暂停顿屏息'})}${input(`shots.${selected}.acting.head`,'头部转动幅度',{placeholder:'只发生轻微受控转动'})}${input(`shots.${selected}.acting.posture`,'肩背与身体姿态',{placeholder:'双肩放松，不出现大幅转身'})}</div></div>`:hint('当前暂无镜头，请先到分镜页添加镜头。');const soundBody=s?`<div class="panel-heading"><div><h3>对白与声音时间轴</h3><p>精确安排对白起止秒数、环境变化与本镜配乐。</p></div></div>`+input(`shots.${selected}.dialogue`,'对白原句',{area:true,placeholder:'角色说了什么？不填写则不添加对白。'})+`<div class="grid two">${select(`shots.${selected}.speakerId`,'说话者',p.characters.map(c=>[c.id,c.name]))}${input(`shots.${selected}.dialogueLanguage`,'语言 / 方言')}${input(`shots.${selected}.delivery`,'台词语气 / 停顿',{placeholder:'例如：压低声音，停顿后反问'})}${select(`shots.${selected}.voiceType`,'声源',[['in','画内对白'],['off','画外对白'],['vo','旁白 VO']])}${input(`shots.${selected}.speechRate`,'估计语速 / 字·音节每秒',{type:'number',min:1,step:.5})}${input(`shots.${selected}.dialogueStart`,'对白起点 / 镜内秒',{type:'number',min:0,step:.1})}${input(`shots.${selected}.dialogueEnd`,'对白终点 / 镜内秒',{type:'number',min:0,step:.1})}</div><div id="dialogue-estimate">${dialogueEstimate(s)}</div>${input(`shots.${selected}.audio`,'环境变化 / 动作音效',{area:true,placeholder:'例如：信纸被握紧时有轻微纸张声；人声出现时风声稍退。'})}${dataliChoice(`shots.${selected}.music`,`perf-shot-music-${selected}`,'本镜配乐覆盖 / 静默',['无背景音乐','本镜暂停配乐（静默）',...GROUPS.bgm.options.filter(x=>x.id!=='none').map(x=>x.label+' · 轻柔铺底')],'留空默认继承全片BGM；填“本镜暂停配乐（静默）”可单镜静音')}<div class="sound-timeline-box"><div class="picker-title"><label>声音设计时间轴 <span class="muted">支持精确到 0.1 秒，严控口型同步</span></label><div class="sound-cue-toolbar">${btn('auto-sound-cues','⚡ 从当前线索生成时间轴','spark','text-btn',`data-index="${selected}"`)}${btn('add-sound-cue','添加时间点','plus','text-btn',`data-index="${selected}"`)}</div></div><div class="sound-cue-list">${s.soundCues.map((q,j)=>`<div class="sound-cue-row"><div class="sound-cue-times">${input(`shots.${selected}.soundCues.${j}.start`,'开始 / 秒',{type:'number',min:0,step:.1})}${input(`shots.${selected}.soundCues.${j}.end`,'结束 / 秒',{type:'number',min:0,step:.1})}${select(`shots.${selected}.soundCues.${j}.kind`,'类型',[['ambience','环境底声'],['sfx','触发音效'],['music','配乐变化'],['dialogue','人声对白'],['foley','动作材质音']])}${btn('delete-sound-cue','','trash','icon-btn',`data-index="${selected}" data-cue="${j}" aria-label="删除声音线索 ${j+1}"`)}</div>${input(`shots.${selected}.soundCues.${j}.cue`,'声音与口型描述',{placeholder:'例如：画外入口传来轻微呼唤 / 对白期间严格控制口型同步'})}</div>`).join('')||hint('可按秒添加雨声、音效、配乐进出与对白起止，精确对齐画面节拍。')}</div></div>`:hint('当前暂无镜头，请先到分镜页添加镜头。');const bgmBody=`<div class="panel-heading"><div><h3>全片背景音乐 / 配乐（BGM）总控</h3><p>全片配乐会进入提示词全局配乐栏，并自动作为未单独指定配乐镜头的默认 BGM。</p></div></div><div class="bgm-global-panel"><div class="grid two">${select('bgm.style','全片配乐曲风',[['','未设置（按各镜设置 / 不写入全局配乐）'],...GROUPS.bgm.options.map(x=>[x.id,x.label])])}${dataliChoice('bgm.mood','bgm-mood-list','情绪走势与节奏',['温柔克制，后半段微暖','紧张压抑，心跳逐步递进','燃向紧凑，高潮瞬间推高','轻松幽默轻快，都市生活感','悲伤缓慢克制，留白收尾'],'例如：前段克制钢琴，冲突时弦乐推高')}${dataliChoice('bgm.instrumentation','bgm-inst-list','主要配器 / 音色',['独奏钢琴 + 温暖大提琴','弦乐拨奏 + 低音脉冲','古筝 + 箫 + 轻打击乐','复古合成器 + 电子鼓点','Lo-fi 电钢琴 + 温暖底噪','木吉他 + 轻铃音'],'例如：独奏钢琴 + 轻柔弦乐铺底')}${select('bgm.vocals','人声形式',[['instrumental','纯器乐 · 无人声歌词（推荐，不抢台词）'],['hum','轻哼 / 无词人声氛围'],['vocal','含人声演唱 / 歌词']])}</div>${input('bgm.custom','配乐进出与台词避让说明',{area:true,placeholder:'例如：0–4秒保持环境安静；事件触发后配乐轻入；角色开口期间音乐音量压低让位。'})}<div class="bgm-global-actions">${s?btn('apply-global-bgm-cues','⚡ 将全局配乐写入当前镜头时间轴','sound','btn subtle small',`data-index="${selected}"`):''}<small class="muted">若某一镜需单独静默，可将该镜「配乐与静默」填为“本镜暂停配乐（静默）”。</small></div></div>`;const segBody=s?segmentEditor(s,selected):hint('当前暂无镜头，请先到分镜页添加镜头。');const perfBodyMap={acting:actingBody,sound:soundBody,bgm:bgmBody,segments:segBody};return heading('PERFORMANCE & SOUND / 表演声音','让情绪，被看见和听见。','点击上方页签快速切换「微表演 / 对白声音 / 全局 BGM / 镜内时序」，无需上下反复滚动。')+shotSelector()+performanceDialogueIndex()+`<section class="web-tabs-shell">${webTabBar('perf-tab',perfTab,pTabs)}<div class="web-tab-panel">${perfBodyMap[perfTab]||actingBody}</div></section>`;}
function dialogueEstimate(s){return s.dialogue?hint(`文本估计约 ${M.fmt(M.estimateDialogue(s.dialogue,s.speechRate))} 秒；可用窗口 ${M.fmt(M.n(s.dialogueEnd)-M.n(s.dialogueStart))} 秒。生成时将强调字音与口型严格同步。`):'';}
function shotSelector(){return `<div class="shot-switcher-panel"><div class="shot-switcher"><label>当前镜头</label><select data-ui="selected-shot">${!p.shots.length?'<option value="">暂无分镜</option>':''}${p.shots.map((s,i)=>`<option value="${i}" ${selected===i?'selected':''}>${String(i+1).padStart(2,'0')} · ${esc(s.title)} · ${s.duration}s</option>`).join('')}<option value="__add__">＋ 去添加分镜</option></select>${btn('auto-enrich-shot','⚡ 补全本镜表演与声音','spark','btn subtle small',`data-index="${selected}"`)}${btn('navigate','返回分镜','arrow','text-btn','data-view="storyboard"')}</div>${p.shots.length?`<div class="timeline-track browser-tab-track compact-tab-track">${p.shots.map((s,i)=>`<button type="button" class="timeline-segment browser-shot-tab ${i===selected?'active':''}" data-action="select-shot" data-index="${i}"><span class="tab-num">${String(i+1).padStart(2,'0')}</span><b>${esc(s.title)}</b><small>${M.fmt(s.duration)}s</small></button>`).join('')}</div>`:''}</div>`;}
function referencesView(){return heading('REFERENCE MATERIAL / 素材编排','每一份参考，都有自己的职责。','本地预览与用途绑定。文件不会自动上传到生成平台。',btn('upload-reference','上传素材','upload','btn primary'))+hint('上传不代表已分析内容。请人工核对素材，再指定它只控制什么、不采用什么。')+`<div class="reference-toolbar">${btn('planned-reference','添加计划素材','plus','btn subtle')}<span class="muted">单文件 ≤ 8 MB · 项目建议定期备份</span></div><div class="reference-grid">${p.references.map((r,i)=>`<article class="reference-card"><div class="reference-thumb">${r.data&&r.type==='image'?`<img src="${esc(r.data)}" alt="${esc(r.name)}">`:icon(r.type==='audio'?'sound':r.type==='video'?'camera':'scene')}<span class="reference-status">${r.data?'已上传':'计划素材'}</span></div><div class="reference-fields">${input(`references.${i}.name`,'素材名称')}${select(`references.${i}.type`,'素材类型',[['image','图片'],['video','视频'],['audio','音频']])}${select(`references.${i}.purpose`,'用途',[['','请选择用途'],['角色外貌','角色外貌'],['场景空间','场景空间'],['道具外观','道具外观'],['首帧','首帧'],['尾帧','尾帧'],['构图','构图'],['影像风格','影像风格'],['动作与运镜','动作与运镜'],['角色音色','角色音色']])}${input(`references.${i}.controls`,'只控制',{placeholder:'林夏的脸型、发型和服装'})}${input(`references.${i}.excludes`,'不采用',{placeholder:'原图背景、其他人物、文字…'})}${toggle(`references.${i}.confirmed`,'已人工核对用途')}<div class="reference-bind"><label>应用到镜头</label><div class="inline-choices">${p.shots.map((s,k)=>`<button data-action="bind-reference" data-id="${r.id}" data-index="${k}" class="tag-button ${s.referenceIds.includes(r.id)?'selected':''}">${String(k+1).padStart(2,'0')} ${esc(s.title)}</button>`).join('')}</div></div>${r.data&&r.type==='audio'?`<audio controls src="${esc(r.data)}"></audio>`:''}${r.data&&r.type==='video'?`<video controls preload="metadata" src="${esc(r.data)}"></video>`:''}<div class="panel-footer">${!r.data?btn('replace-reference','补充文件','upload','text-btn',`data-id="${r.id}"`):''}${btn('delete-reference','删除','trash','text-btn danger',`data-index="${i}"`)}</div></div></article>`).join('')||`<div class="empty-state">${icon('layers')}<h3>先整理参考，再开始生成</h3><p>角色、场景、道具和声音，可以各自绑定用途。</p>${btn('upload-reference','选择本地文件','upload','btn subtle')}</div>`}</div>`;}
function specsView(){const sTabs=[['story','01','故事与连贯',p.chainLastFrame||p.cutFrameCheck?'已开防跳/续接':'默认'],['format','02','画面与帧率',`${M.aspect(p)}·${p.resolution}`],['restrictions','03','字幕与负面词',p.negativePrompts?.length?`${p.negativePrompts.length}项排雷`:'可选'],['data','04','备份与导入','JSON备份']];const storyBody=input('title','项目名称')+input('logline','一句话剧情',{area:true})+`<div class="grid two">${input('targetDuration','目标成片时长 / 秒',{type:'number',min:.1,step:1})}${select('timing','时间轴排布',[['ordered','顺序排布 · 自动顺延'],['free','自由起点 · 检查缺口与重叠']])}</div>`+toggle('chainLastFrame','尾帧接下一镜首帧（含5条逐镜生成与逐秒抽帧铁律）','勾选后要求一镜一镜按顺序生成、上镜尾帧作下镜输入图、逐秒抽帧检查、提前演到后面时截断、重做需全量重接。')+toggle('cutFrameCheck','切点前后两帧检查（仅生成阶段防跳校验）','勾选后要求生成时上一镜尾帧与下一镜首帧保持头发/手臂/衣服/位置一致；出现漂移须在生成阶段重修，后期转场仍按剪辑执行表无条件执行。');const formatBody=`<div class="grid two">${select('resolution','交付分辨率',['720P','1080P','2K','4K','DCI 4K','8K','自定义'])}${select('format','画幅',['9:16','16:9','2.39:1','21:9','1.85:1','1:1','4:3','3:4','4:5','2:1','自定义'])}${select('fps','帧率',[[12,'12 fps · 抽帧/动画'],[23.976,'23.976 fps'],[24,'24 fps · 电影感'],[25,'25 fps'],[29.97,'29.97 fps'],[30,'30 fps'],[48,'48 fps'],[50,'50 fps'],[60,'60 fps'],[120,'120 fps'],['自定义','自定义帧率']])}${select('platform','目标平台',['通用自然语言','Seedance / 即梦','可灵 Kling','Veo','Sora','其他平台'])}</div>${p.format==='自定义'?input('customFormat','自定义画幅比例',{placeholder:'例如 2.39:1'}):''}${p.fps==='自定义'?input('customFps','自定义帧率',{type:'number',min:.1,step:.001}):''}${p.resolution==='自定义'?`<div class="grid two">${input('customWidth','像素宽度',{type:'number',min:1,step:1})}${input('customHeight','像素高度',{type:'number',min:1,step:1})}</div>`:''}<div class="resolution-preview"><strong>${M.resolution(p)}</strong><span>${M.aspect(p)} · ${M.frameRate(p)}fps · 交付目标</span></div>${hint('选择8K不会提升已有画质。当前平台输出采用通用自然语言，具体参数、时长与参考语法提交前需按平台核对。')}`;const restBody=select('subtitles','对白字幕',[['none','不叠加对白字幕'],['post','后期添加字幕'],['specified','按指定内容添加']])+input('screenText','故事中必须出现的画内文字',{area:true,placeholder:'例如：信封右下角写“林夏亲启”；无要求则留空。',hint:'画内招牌、信件文字与对白字幕分别处理。'})+input('restrictions','连续性与画面要求',{area:true})+`<div class="negative-toolbar"><span class="muted">按当前项目道具、对白与运镜风险智能组合全局排雷词：</span>${btn('suggest-negatives','⚡ 智能推荐场景化负面词','spark','btn subtle small')}</div>`+picker('negative','negativePrompts');const dataBody=`<div class="data-actions">${btn('export','完整项目备份','download','btn subtle')}${btn('import','导入项目','upload','btn subtle')}${btn('duplicate-project','复制当前项目','copy','btn subtle')}${btn('delete-project','删除当前项目','trash','btn subtle danger')}</div>${hint('项目和参考文件保存在当前浏览器。清理浏览器数据会删除本地草稿；完整JSON备份可携带已上传素材。')}`;const specMap={story:storyBody,format:formatBody,restrictions:restBody,data:dataBody};return heading('PROJECT SETTINGS / 项目规格','把创作意图，整理成项目。','点击上方页签切换「故事连贯 / 画面帧率 / 字幕负面词 / 数据备份」，一屏完成配置。')+`<section class="web-tabs-shell">${webTabBar('specs-tab',specsTab,sTabs)}<div class="web-tab-panel">${specMap[specsTab]||storyBody}</div></section>`;}
function outputPanel(){if(view==='video')return videoOutputPanel();const issues=hasCreativeContent(p)?M.checkProject(p):[],errors=issues.filter(x=>x.severity==='error').length,warnings=issues.filter(x=>x.severity==='warning').length;return `<div class="preview-heading"><div><span class="eyebrow">PROMPT OUTPUT</span><h2>你的提示词 <span class="live-dot"></span></h2></div>${btn('close-preview','','close','icon-btn mobile-only','aria-label="关闭预览"')}</div><div class="preview-tabs"><button data-action="right-tab" data-value="prompt" class="${rightTab==='prompt'?'active':''}">${icon('spark')}实时输出</button><button data-action="right-tab" data-value="checks" class="${rightTab==='checks'?'active':''}">${icon('check')}检查<span class="count ${errors?'red':''}">${errors+warnings}</span></button></div>${rightTab==='prompt'?`<div class="output-controls"><select aria-label="提示词输出方式" data-bind="${p.mode==='commerce'?'commerce.output':'output'}">${(p.mode==='commerce'?[['image','商品图片提示词'],['video','广告视频提示词'],['plan','广告分段脚本']]:OUTPUTS).map(([id,l])=>`<option value="${id}" ${(p.mode==='commerce'?p.commerce?.output:p.output)===id?'selected':''}>${l}</option>`).join('')}</select><div class="language-switch"><button data-action="language" data-value="zh" class="${p.language==='zh'?'active':''}">中</button><button data-action="language" data-value="en" class="${p.language==='en'?'active':''}">EN</button></div></div>${p.mode!=='commerce'&&p.shots.length?`<div class="output-quick-modes"><button type="button" data-action="output-mode" data-value="full" class="${p.output==='full'?'active':''}">全片</button><button type="button" data-action="output-mode" data-value="shot" class="${p.output==='shot'?'active':''}">仅第${selected+1}镜</button><button type="button" data-action="output-mode" data-value="first" class="${p.output==='first'?'active':''}">首帧</button><button type="button" data-action="output-mode" data-value="plain" class="${p.output==='plain'?'active':''}">自然语言</button></div>`:''}<div class="output-meta"><span>${icon('check')}随设定实时更新</span><span id="char-count">${M.generate(p,selected).length.toLocaleString()} 字符</span></div>${['shot','first','last'].includes(p.output)?`<div class="current-shot-label">当前：${String(selected+1).padStart(2,'0')} · ${esc(p.shots[selected]?.title||'无镜头')}</div>`:''}<div class="prompt-scroll"><div class="prompt-paper" id="prompt-text" tabindex="0">${M.generate(p,selected)?formattedPrompt():emptyPromptMarkup()}</div></div><div class="output-footnote">${icon('info')}分辨率和帧率属于交付目标；提交时请核对平台设置。${p.language==='en'?'<br>内置词条已切换英文，自由文本保留原文。':''}</div><div class="copy-area">${btn('copy','复制提示词','copy','btn primary copy-primary',M.generate(p,selected)?'':'disabled aria-disabled="true"')}${p.mode!=='commerce'&&p.shots[selected]?btn('copy-shot',`仅复制第${selected+1}镜`,'','btn subtle small',`data-index="${selected}" title="只复制当前选中镜头的提示词"`):''}${btn('export-text','','download','btn subtle square','title="下载当前提示词" aria-label="下载提示词"')}</div><div class="output-secondary">${btn('edit-output','手工编辑版本','settings','text-btn')}${btn('export-csv','导出分镜表','board','text-btn')}</div>`:`<div class="checks-summary"><span class="check-summary-icon ${errors?'has-error':''}">${icon(errors?'alert':'check')}</span><div><strong>${errors?`${errors} 项需要修正`:warnings?`${warnings} 项建议检查`:'基础检查已完成'}</strong><p>核对已声明的事实，保留你的创作判断。</p></div></div><div class="checks-list">${issues.map((issue,i)=>`<button class="check-item ${issue.severity}" data-action="issue" data-index="${i}">${icon(issue.severity==='error'?'alert':issue.severity==='warning'?'info':'check')}<span><strong>${esc(issue.title)}</strong><small>${issue.index!==null?'镜头 '+(issue.index+1)+' · ':''}${esc(issue.detail)}</small></span>${icon('chevron')}</button>`).join('')||`<div class="empty-check">${icon('check')}没有发现基础结构冲突。</div>`}${hint('剧情合理性、自由文本中的复杂因果和生成后的实际穿帮，需要人工或AI进一步审阅。')}</div><div class="checks-bottom">${btn('navigate','回到分镜调整','arrow','btn subtle','data-view="storyboard"')}</div>`}`;}
function formattedPrompt(){return M.generate(p,selected).split('\n').map(line=>{const header=/^(负面提示词|NEGATIVE PROMPT|全局影像风格|角色与造型|逐镜安排|画面要求|交付目标|首尾帧衔接要求|切点前后两帧检查|【生成阶段规范】|【后期合并剪辑与转场执行表】|【本镜后期剪辑备忘|GENERATION-STAGE SPEC|EDITING & TRANSITION EXECUTION TABLE|POST-PRODUCTION MERGE MEMO|LAST-FRAME-TO-FIRST-FRAME|CUT-POINT TWO-FRAME CHECK|VISUAL DIRECTION|CHARACTERS|SHOT SEQUENCE|FRAME REQUIREMENTS|DELIVERY TARGET)/.test(line);const sub=/^(【(导演意图|镜内时间轴|声音时间轴|连续性约束|AI短剧转场规范[^】]*)】|执行铁律|术语定义|切点清单|素材余量总账|MANDATORY RULE|TERM DEFINITIONS|CUT-POINT SCHEDULE|FOOTAGE BUDGET|DIRECTORIAL INTENT|IN-SHOT TIMELINE|SOUND TIMELINE|CONTINUITY LOCK|AI SHORT-DRAMA TRANSITION SPEC)/.test(line);const cut=/^(——\s|场景过渡：|切点前后两帧检查|切点两帧检查（|\d+\.\s+\d{2}:)/.test(line);const time=/^(\[?\d+(\.\d+)?([–—-]\d+(\.\d+)?)?(秒|s|｜)|\d+\.\s)/.test(line);return `<div class="prompt-line ${header?'prompt-section':''} ${sub?'prompt-subhead':''} ${cut?'prompt-cutline':''} ${time?'prompt-timestamp':''}">${esc(line)||'<br>'}</div>`;}).join('');}
function render(){closeSuggestions();document.body.classList.toggle('home-surface',surface==='home');document.body.classList.toggle('quick-mode',p.mode==='quick');if(surface==='home'){$('#app').innerHTML=homeMarkup(p,{hasDraft:!transientProject&&hasCreativeContent(p),art});return;}selected=Math.max(0,Math.min(selected,p.shots.length-1));castSelected=Math.max(0,Math.min(castSelected,p.characters.length-1));sceneSelected=Math.max(0,Math.min(sceneSelected,p.scenes.length-1));const scroll=$('#main')?.scrollTop||0,promptScroll=$('.prompt-scroll')?.scrollTop||0;$('#app').innerHTML=shell();renderMain();renderOutput();restoreEditorScroll($('#main'),scroll);restoreEditorScroll($('.prompt-scroll'),promptScroll);updateHistoryButtons();}
function renderMainBase(){const renders={ai:aiStudioView,video:videoStudioView,connections:connectionView,start:startView,commerce:commerceView,storyboard,style:styleView,characters:charactersView,scenes:scenesView,camera:cameraView,performance:performanceView,references:referencesView,specs:specsView};$('#main').innerHTML=renders[view]();if(view==='commerce'){const groups=[['product','商品与卖点'],['visual','展示与构图'],['timeline','广告分段'],['sources','参考方法']];$('.page-heading').insertAdjacentHTML('afterend','<div class="character-groups commerce-tabs">'+groups.map(([k,l])=>btn('commerce-group',l,'',`tag-button ${commerceGroup===k?'selected':''}`,`data-value="${k}"`)).join('')+'</div>');const panels=Array.from(document.querySelectorAll('#main>.panel'));panels[0].hidden=commerceGroup!=='product';panels[1].hidden=commerceGroup!=='visual';if(p.commerce.output!=='image')panels[2].hidden=commerceGroup!=='timeline';panels.at(-1).hidden=commerceGroup!=='sources';if(commerceGroup==='timeline'&&p.commerce.output==='image')panels[0].hidden=false;}}
function renderOutput(){if(!p||surface==='home'||!$('#preview'))return;const scroll=$('.prompt-scroll')?.scrollTop||0;$('#preview').innerHTML=outputPanel();const area=$('.prompt-scroll');if(area)area.scrollTop=scroll;const el=$('#mobile-issue-count');if(el){const count=hasCreativeContent(p)?M.checkProject(p).filter(x=>x.severity!=='info').length:0;el.textContent=count?`${count}项待检查`:'';}}
function updateHistoryButtons(){const a=$('[data-action="undo"]'),b=$('[data-action="redo"]');if(a)a.disabled=!undo.length;if(b)b.disabled=!redo.length;}
function remember(key=''){if(key&&lastEdit===key)return;undo.push(M.clone(p));if(undo.length>60)undo.shift();redo=[];lastEdit=key;updateHistoryButtons();}
function changed({refresh=false}={}){transientProject=false;revision++;saveStatus='正在保存…';saveFailed=false;p.updatedAt=Date.now();clearTimeout(saveTimer);const label=$('#save-label');if(label){label.textContent='正在保存…';label.closest('.local-label').classList.remove('failed');}saveTimer=setTimeout(persist,450);if(refresh)render();else {renderOutput();updateJourney();$$('[data-stat="duration"]').forEach(el=>el.textContent=M.fmt(M.totalDuration(p)));const t=$('.project-title');if(t)t.innerHTML=esc(p.title)+icon('chevron');const timelineEl=$('.timeline-panel');if(timelineEl)timelineEl.outerHTML=timelineView();M.timeline(p).forEach((t,i)=>{const card=$(`#shot-${i}`);if(card){const range=$('.shot-subtitle>span:first-child',card),badge=$('.duration-badge',card),title=$('.shot-select strong',card);if(range)range.textContent=`${M.fmt(t.start)}–${M.fmt(t.end)}s`;if(badge)badge.textContent=M.fmt(t.duration)+'s';if(title)title.textContent=p.shots[i].title;}});const estimate=$('#dialogue-estimate');if(estimate&&p.shots[selected])estimate.innerHTML=dialogueEstimate(p.shots[selected]);}}
async function persist(){clearTimeout(saveTimer);if(transientProject)return true;const r=revision,snapshot=M.clone(p);try{await DB.saveProject(snapshot);DB.lastProject(snapshot.id);if(r===revision){saveStatus='已保存到本地';saveFailed=false;if($('#save-label'))$('#save-label').textContent=saveStatus;}return true;}catch(e){saveStatus='保存失败 · 请导出备份';saveFailed=true;const l=$('#save-label');if(l){l.textContent=saveStatus;l.closest('.local-label').classList.add('failed');}toast('本地保存失败，请先导出项目备份。','error');return false;}}
function toast(text,type=''){const e=$('#toast');e.textContent=text;e.className='show '+type;clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.className='',3600);}
function modal(title,body,footer='',kind=''){const d=$('#modal');d.dataset.kind=kind;d.innerHTML=`<div class="modal-head"><div><span class="eyebrow">JINGXU STUDIO</span><h2>${title}</h2></div>${btn('close-modal','','close','icon-btn','aria-label="关闭弹窗"')}</div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!d.open)d.showModal();}
function closeModal(){$('#modal').close();$('#modal').innerHTML='';$('#modal').dataset.kind='';}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('已复制，可以粘贴到生成平台。');}catch{modal('复制提示词',`<p class="help">浏览器未允许直接复制，请选择下面的文本后复制。</p><textarea id="manual-copy" class="manual-output">${esc(text)}</textarea>`,btn('close-modal','完成','','btn primary'));$('#manual-copy').select();}}
function download(name,text,type='application/json'){const b=new Blob([text],{type}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function safeName(){return (p.title||'镜序项目').replace(/[<>:"/\\|?*]/g,'-');}
function exportProject(includeAssets=true){const project=M.clone(p);if(!includeAssets)project.references.forEach(r=>{r.data='';r.confirmed=false;});download(`${safeName()}.jingxu.json`,JSON.stringify({application:'镜序',exportedAt:new Date().toISOString(),project},null,2));toast(includeAssets?'已导出完整项目，包含已上传的参考素材。':'已导出轻量项目，参考素材保留为计划。');}
async function applyImportedText(rawText){const imported=M.parseImportText(rawText);await changeProject(imported);toast(`已导入「${imported.title}」为独立副本。`);}
async function applyImportedFile(file){if(!file)return;if(file.size>40*1024*1024)throw Error('项目文件超过40MB，请导入较小的备份。');await applyImportedText(await file.text());}
function importModal(){modal('导入项目',hint('支持导入镜序导出的完整 / 轻量 .jingxu.json 或 .json 项目文件。导入后会作为独立副本打开，当前项目与已有本地记录均不会被覆盖。')+`<div class="import-dropzone" id="import-dropzone">${icon('upload')}<div><strong>选择项目文件，或将 .jingxu.json 拖放到此处</strong><small>支持 40MB 以内备份文件（含人物、场景、分镜、AI 设定与参考图）</small></div>${btn('pick-project-file','选择项目文件','folder','btn primary small')}</div><label class="field import-json-field"><span>或直接粘贴项目 JSON 内容（可选）</span><textarea id="import-json-input" class="manual-output" placeholder='可在此粘贴 {"application":"镜序","project":{...}} 或导出的 JSON 文本'></textarea></label>`,btn('close-modal','取消','','btn subtle')+btn('confirm-import-text','从粘贴 JSON 导入','check','btn primary'),'import');}
async function changeProject(next){clearTimeout(saveTimer);await persist();p=next;if(p.aiSuggestion)p.aiSuggestion.projectId=p.id;updateSurface('studio');selected=castSelected=sceneSelected=0;undo=[];redo=[];lastEdit='';orderCache={};view=p.mode==='commerce'?'commerce':hasCreativeContent(p)?'storyboard':'start';assetFlow=null;expandedShots.clear();expandedTextAreas.clear();transientProject=false;revision++;closeModal();render();await persist();$('#main').scrollTop=0;}
function templateModal(id){const t=TEMPLATES.find(x=>x.id===id)||TEMPLATES[0];modal('从一个故事开始',`<div class="template-preview-art">${art(t.theme)}<span>氛围构图示意</span></div><h3>${t.name}</h3><p class="help">${t.desc||'用一套可修改的分镜开始新的创作。'}</p><div class="template-beats">${t.titles.map((x,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><strong>${x}</strong><small>${t.durations[i]}s</small></div>`).join('')}</div>${hint('将新建一个模板项目。当前项目保留，不会被覆盖。')}`,btn('templates','其他模板','','btn subtle')+btn('apply-template','使用这套模板','arrow','btn primary',`data-id="${id}"`));}
function templatesModal(){modal('选择你的故事起点',`<p class="help">12套可编辑模板。人物、质感、动作和时长都可以重新定义。</p>${btn('blank-project','从零开始 · 空白项目','plus','btn primary')}<p class="help">不预填人物、场景或提示词。也可以选择下方示例。</p><div class="template-grid">${TEMPLATES.map(t=>`<button class="template-tile" data-action="template-preview" data-id="${t.id}"><div>${art(t.theme)}</div><span class="template-tag">${t.tag}</span><strong>${t.name}</strong><small>3个镜头 · ${t.durations.reduce((a,b)=>a+b,0)}秒</small></button>`).join('')}</div>`,'','templates');}
function shotCameraModal(i){const s=p.shots[i];if(!s)return;const c=M.camera(p,s),field=(k,l,values)=>`<label class="field"><span>${l}</span><select aria-label="${l}" data-bind="shots.${i}.camera.${k}">${values.map(v=>`<option value="${v[0]}" ${String(v[0])===String(c[k])?'selected':''}>${esc(v[1])}</option>`).join('')}</select></label>`;modal(`本镜摄影 · ${esc(s.title)}`,hint('未覆盖字段继承全局；物理推进(Dolly In)/后拉改变机位位置，光学变焦请保持“不变焦”。')+`<div class="grid two">${['framing','angle','composition','move','moveDistance','speed','stability','lens','focus','rotation','zoom'].map(k=>field(k,GROUPS[k].label,M.options(p,k).map(x=>[x.id,x.label]))).join('')}${c.move==='orbit'?field('direction','俯视方向',[['cw','顺时针'],['ccw','逆时针']])+field('orbit','角度',[[45,'45°'],[90,'90°'],[180,'180°'],[360,'360°']]):''}</div><div class="grid two">${input(`shots.${i}.camera.start`,'摄影机起始位置',{placeholder:'从上一镜中景起幅…'})}${input(`shots.${i}.camera.end`,'摄影机结束状态',{placeholder:'面部占画面主要区域…'})}</div>${motionDiagram(c)}`,btn('reset-shot-camera','恢复继承全局','undo','btn subtle',`data-index="${i}"`)+btn('close-modal','完成','check','btn primary'),'camera');$('#modal').dataset.index=i;}
function transitionModalOptionsHtml(s,i){const q=(transitionModalState.q||'').trim().toLowerCase(),cat=transitionModalState.cat||'all',list=M.options(p,'transition').filter(o=>(cat==='all'||o.cat===cat)&&(!q||`${o.label} ${o.zh} ${o.en} ${o.tip||''}`.toLowerCase().includes(q)));if(!list.length)return '<div class="small-empty">没有找到匹配的转场效果，换个关键词或切换分类试试。</div>';return list.map(o=>{const catName=TRANSITION_CATEGORIES.find(c=>c.id===o.cat)?.short||'通用',active=(s.transition||'cut')===o.id;return `<button type="button" class="trans-option-card ${active?'active':''}" data-action="select-modal-transition" data-index="${i}" data-value="${esc(o.id)}" title="${esc(o.tip||o.zh)}"><div class="trans-card-top"><strong>${esc(o.label)}</strong><span>${esc(catName)}</span></div><small>${esc(o.zh||o.tip||'')}</small></button>`;}).join('');}
function transitionModal(i){const s=p.shots[i],next=p.shots[i+1];if(!s)return;s.transitionSpec??=M.transitionSpecDefaults();transitionModalState.index=i;const scA=p.scenes.find(x=>x.id===s.sceneId),scB=next?p.scenes.find(x=>x.id===next.sceneId):null,isCross=Boolean(scA&&scB&&scA.id!==scB.id),curOpt=M.options(p,'transition').find(o=>o.id===(s.transition||'cut')),autoPreview=M.buildTransitionSpec(p,i)||{},allOpts=M.options(p,'transition'),cats=[{id:'all',short:'全部分类'},...TRANSITION_CATEGORIES];const specInput=(k,l,ph='',isNum=false)=>`<label class="field"><span>${l}</span><input ${isNum?'type="number" min="0" step="0.1"':''} aria-label="${l}" data-bind="shots.${i}.transitionSpec.${k}" value="${esc(s.transitionSpec[k]??'')}" placeholder="${esc(String(autoPreview[k]??ph))}"></label>`;modal(`场景与镜头转场设计 · ${String(i+1).padStart(2,'0')} → ${next?String(i+2).padStart(2,'0'):'片尾'}`,hint((isCross?`跨场景过渡（${esc(scA.name)} → ${esc(scB.name)}）：`:'同场景/连续镜头切换：')+'选择 6 大类 108 种转场之一，或点“⚡ 智能适配”自动填写下方 AI 短剧十项转场规范。')+`<div class="trans-modal-header"><div class="trans-current-summary"><span>当前选用（第1项）</span><strong>${esc(curOpt?.label||M.label(p,'transition',s.transition||'cut'))}</strong><small>${esc(curOpt?.tip||curOpt?.zh||'')}</small></div>${next?btn('auto-transition-spec','⚡ 智能适配转场与十项规范','spark','btn primary small',`data-index="${i}"`):''}</div><div class="trans-modal-filters"><div class="trans-cat-pills">${cats.map(c=>`<button type="button" class="tag-button ${transitionModalState.cat===c.id?'selected':''}" data-action="transition-modal-cat" data-index="${i}" data-value="${c.id}">${esc(c.short)} <small>${c.id==='all'?allOpts.length:allOpts.filter(o=>o.cat===c.id).length}</small></button>`).join('')}</div><label class="field trans-search-field"><span>搜索全部转场</span><input data-ui="transition-search" value="${esc(transitionModalState.q||'')}" placeholder="搜索：淡入 / 甩镜 / 叠化 / 火焰 / 遮罩 / 声音桥 / L-Cut…"></label></div><div class="trans-cards-grid" id="transition-modal-cards">${transitionModalOptionsHtml(s,i)}</div><div class="trans-spec-box"><div class="picker-title"><label>AI 短剧十项转场规范 <span class="muted">留空字段将按所选转场与前后镜自动生成</span></label></div><div class="grid two">${specInput('fromFrame','02 前镜尾帧状态（第2项）')}${specInput('trigger','03 转场触发动作（第3项）')}${specInput('process','04 视觉过渡过程（第4项）')}${specInput('direction','05 运动轨迹/方向（第5项）')}${specInput('duration','06 过渡时长 / 秒（第6项）','0.4',true)}${specInput('toFrame','07 后镜首帧落幅（第7项）')}${specInput('motionContinuity','08 动势与节奏衔接（第8项）')}${specInput('audioBridge','09 声音桥 / 音效过渡（第9项）')}</div>${specInput('continuityLock','10 连续性与禁止穿帮（第10项）')}</div>`,btn('close-modal','完成','check','btn primary'),'transition');$('#modal').dataset.index=i;}
function shotMenu(i){const s=p.shots[i];modal(`镜头操作 · ${esc(s.title)}`,`<div class="menu-grid">${btn('move-up','上移镜头','arrow','btn subtle',`data-index="${i}" ${i===0?'disabled':''}`)}${btn('move-down','下移镜头','arrow','btn subtle',`data-index="${i}" ${i===p.shots.length-1?'disabled':''}`)}${btn('duplicate-shot','复制镜头','copy','btn subtle',`data-index="${i}"`)}${btn('split-shot','拆为两个镜头','board','btn subtle',`data-index="${i}"`)}${btn('merge-shot','与下一镜合并','layers','btn subtle',`data-index="${i}" ${i===p.shots.length-1?'disabled':''}`)}${btn('delete-shot','删除本镜','trash','btn subtle danger',`data-index="${i}"`)}</div>${hint('拆合镜会先显示调整方式。含对白或细分时间段时，需要先手动安排内容归属，避免误改时序。')}`);}
function preferencesModal(filter=''){const favorites=Object.entries(GROUPS).flatMap(([key,g])=>M.options(p,key).map(o=>({...o,key,group:g.label,count:prefs.usage[`${key}:${o.id}`]?.count||0,favorite:prefs.favorites.includes(`${key}:${o.id}`)}))).filter(x=>(!filter||`${x.label} ${x.zh} ${x.en}`.toLowerCase().includes(filter.toLowerCase()))&&(filter||x.favorite||x.count)).sort((a,b)=>Number(b.favorite)-Number(a.favorite)||b.count-a.count);modal('常用与收藏',`<div class="grid two"><label class="field"><span>排序方式</span><select data-ui="preference-sort"><option value="usage" ${prefs.sort!=='original'?'selected':''}>收藏 → 次数 → 最近使用</option><option value="original" ${prefs.sort==='original'?'selected':''}>词库原始顺序</option></select></label><label class="field"><span>搜索全部词库</span><input data-ui="catalog-search" value="${esc(filter)}" placeholder="搜索：环绕 / 手机 / 毛孔…"></label></div><div id="preference-results">${preferenceRows(favorites)}</div>${prefs.characterTemplates?.length?`<h3 class="modal-subtitle">保存的角色模板</h3>${prefs.characterTemplates.map((c,i)=>`<div class="saved-template"><span><strong>${esc(c.name)}</strong><small>${esc(c.variant)}</small></span>${btn('apply-character-template','添加到项目','plus','text-btn',`data-index="${i}"`)}${btn('remove-character-template','','trash','icon-btn',`data-index="${i}" aria-label="删除角色模板"`)}</div>`).join('')}`:''}`,btn('reset-usage','清空使用次数','trash','btn subtle')+btn('close-modal','完成','check','btn primary'),'preferences');}
function preferenceRows(rows){return rows.length?`<div class="preference-list">${rows.map(x=>`<div><button class="favorite ${x.favorite?'is-favorite':''}" data-action="favorite" data-key="${x.key}" data-value="${x.id}" aria-label="收藏${esc(x.label)}">${icon('star')}</button><span><strong>${esc(x.label)}</strong><small>${x.group}</small></span><em>${x.count} 次</em></div>`).join('')}</div>`:'<div class="small-empty">选择常用选项或点击星标，它们会出现在这里。</div>';}
function moveShot(from,to){if(to<0||to>=p.shots.length||from===to)return;remember();const [s]=p.shots.splice(from,1);p.shots.splice(to,0,s);selected=to;changed({refresh:true});toast('顺序已调整，时间轴与引用已更新。');}
async function removeEntity(kind,index){const list=p[kind],entity=list[index];if(!entity)return;const id=entity.id,used=kind==='characters'?p.shots.filter(s=>s.characterIds.includes(id)||s.speakerId===id&&s.dialogue):kind==='scenes'?p.shots.filter(s=>s.sceneId===id):kind==='props'?p.shots.filter(s=>s.propId===id):[];if(used.length){toast(`仍有 ${used.length} 个镜头引用，请先修改镜头引用。`,'error');return;}remember();list.splice(index,1);changed({refresh:true});toast('已删除，可通过撤销恢复。');}
function persistPrefs(){try{DB.savePrefs(prefs);return true;}catch{toast('偏好保存失败，请检查浏览器存储空间。','error');return false;}}
