document.addEventListener('input',e=>{const el=e.target;if(!p)return;if(el.matches('[data-bind]')&&!['checkbox','select-one'].includes(el.type)){const path=el.dataset.bind;remember(path);let value=el.type==='number'||el.type==='range'?(el.value===''&&path.endsWith('.transitionSpec.duration')?'':Number(el.value)):el.value;if(path.includes('.layout.'))value=Math.max(5,Math.min(95,value));set(p,path,value);if(path.startsWith('aiBrief.'))updateAIBriefControls();if(el.tagName==='TEXTAREA')fitTextarea(el);if(['format','resolution','fps','customWidth','customHeight','customFps','customFormat'].includes(path))p.specsChosen=true;changed();}if(el.dataset.ui==='catalog-search'){const query=el.value.toLowerCase();const rows=Object.entries(GROUPS).flatMap(([key,g])=>M.options(p,key).map(o=>({...o,key,group:g.label,count:prefs.usage[`${key}:${o.id}`]?.count||0,favorite:prefs.favorites.includes(`${key}:${o.id}`)}))).filter(x=>`${x.label} ${x.zh} ${x.en}`.toLowerCase().includes(query));$('#preference-results').innerHTML=preferenceRows(rows);}if(el.dataset.ui==='transition-search'){transitionModalState.q=el.value;const idx=transitionModalState.index,box=$('#transition-modal-cards');if(box&&p.shots[idx])box.innerHTML=transitionModalOptionsHtml(p.shots[idx],idx);}});
document.addEventListener('change',async e=>{const el=e.target;if(!p)return;try{
 if(el.dataset.aiScope){aiScopes[el.dataset.aiScope]=el.checked;return;}if(el.dataset.ui==='ai-apply-mode'){aiApplyMode=el.value;return;}if(el.dataset.videoRef){remember();const d=initVideoDraft(),ids=d.referenceIds||[],at=ids.indexOf(el.dataset.videoRef);at<0?ids.push(el.dataset.videoRef):ids.splice(at,1);d.referenceIds=ids;changed();return;}
 if(el.dataset.ui==='shot-camera-preset'){const shot=p.shots[Number(el.dataset.index)];if(el.value==='__create__'){openCameraLibraryForShot(shot);return;}const builtIn=/^builtin:(\d+)$/.exec(el.value),entry=builtIn?PRESETS.camera[Number(builtIn[1])]:null;const template=entry?makeCameraTemplate(p,entry.name,{...M.camera(p,shot),...entry.data},el.value):cameraTemplates().find(x=>x.id===el.value);if(template){remember();applyCameraTemplate(p,shot,template);changed({refresh:true});}return;}
 if(el.dataset.ui==='load-camera-draft'){if(el.value)loadCameraDraft(el.value);return;}
 if(el.tagName==='SELECT'&&el.dataset.ui?.startsWith('preset-')&&el.value!==''){const index=Number(el.value);el.value='';openPreset(el.dataset.ui.slice(7),index);return;}if(el.dataset.ui==='preset-empty'){openPreset(activePreset.kind,activePreset.index,el.checked);return;}
 if(el.matches('[data-bind]')){const path=el.dataset.bind;if(el.value==='__add__'&&relationFor(path)){startAssetFlow(path);return;}if(el.dataset.attribute&&el.value==='__custom'){modal('自定义属性','<label class="field"><span>属性描述</span><input id="attribute-custom"></label>',btn('save-attribute','应用自定义','','btn primary',`data-path="${path}"`));return;}if(el.dataset.pickerKey&&get(p,path)!==el.value&&el.value){const k=el.dataset.pickerKey+':'+el.value;prefs.usage[k]={count:(prefs.usage[k]?.count||0)+1,time:Date.now()};persistPrefs();}if(el.type==='checkbox'||el.tagName==='SELECT'){remember();let value=el.type==='checkbox'?el.checked:el.value;if(['aiBrief.duration','aiBrief.shotCount','videoDraft.duration'].includes(path))value=Number(value);if((path==='fps'&&value!=='自定义')||path==='camera.orbit'||path==='cameraDraft.orbit'||path.endsWith('.camera.orbit'))value=Number(value);set(p,path,value);if(path==='aiBrief.chainLastFrame')p.chainLastFrame=!!value;if(path==='chainLastFrame'&&p.aiBrief)p.aiBrief.chainLastFrame=!!value;if(path==='aiBrief.cutFrameCheck')p.cutFrameCheck=!!value;if(path==='cutFrameCheck'&&p.aiBrief)p.aiBrief.cutFrameCheck=!!value;if(path==='aiBrief.bgmStyle'){if(value==='none')p.aiBrief.bgmMode='none';else if(value&&(p.aiBrief.bgmMode==='auto'||p.aiBrief.bgmMode==='none'))p.aiBrief.bgmMode='guided';const modeEl=$('select[data-bind="aiBrief.bgmMode"]');if(modeEl)modeEl.value=p.aiBrief.bgmMode;}if(path==='aiBrief.bgmMode'){if(value==='none')p.aiBrief.bgmStyle='none';else if(p.aiBrief.bgmStyle==='none')p.aiBrief.bgmStyle='';const styleEl=$('select[data-bind="aiBrief.bgmStyle"]');if(styleEl)styleEl.value=p.aiBrief.bgmStyle;}if(path==='videoDraft.source'&&value!=='custom'){refreshVideoPrompt(false);return;}const transMatch=/^shots\.(\d+)\.transition$/.exec(path);if(transMatch){const ts=p.shots[Number(transMatch[1])];if(ts)ts.transitionSpec=M.transitionSpecDefaults();}if(/^shots\.\d+\.camera\./.test(path)){const shot=p.shots[Number(path.split('.')[1])];delete shot.cameraPresetId;delete shot.cameraPresetName;}if(['format','resolution','fps'].includes(path))p.specsChosen=true;}lastEdit='';changed();if($('#modal').dataset.kind==='camera'&&path.includes('.camera.')){renderMain();shotCameraModal(Number($('#modal').dataset.index));}else if(!$('#modal').open&&path.startsWith('aiBrief.')){updateAIBriefControls();}else if(!$('#modal').open&&(el.tagName==='SELECT'||el.type==='checkbox'||path.endsWith('.dialogue')||path.includes('.layout.'))){renderMain();}}
 if(el.dataset.ui==='selected-shot'){if(el.value==='__add__'){view='storyboard';render();document.querySelector('[data-action="add-shot"]')?.click();return;}selected=Number(el.value);renderMain();renderOutput();}
 if(el.dataset.ui==='preference-sort'){prefs.sort=el.value;persistPrefs();orderCache={};renderMain();}
 if(el.id==='project-file'&&el.files[0]){await applyImportedFile(el.files[0]);el.value='';}
 if(el.id==='reference-file'){const replaceId=el.dataset.replace,files=[...el.files];let count=0;remember();for(const file of replaceId?files.slice(0,1):files){if(file.size>8*1024*1024){toast(`${file.name} 超过8MB，未导入。`,'error');continue;}if(!/^(image\/(png|jpeg|webp|gif)|audio\/|video\/)/i.test(file.type)){toast('不支持这个素材格式。','error');continue;}const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const r={id:replaceId||M.uid(),name:file.name,type:file.type.split('/')[0],purpose:'',controls:'',excludes:'',data,confirmed:false};if(replaceId){const at=p.references.findIndex(x=>x.id===replaceId);p.references[at]={...p.references[at],data,type:r.type,confirmed:false};}else p.references.push(r);count++;}el.value='';changed({refresh:true});if(count){if(assetFlow?.kind==='references'&&p.references.length){remember();set(p,assetFlow.path,p.references.at(-1).id);changed({refresh:true});}toast(`已导入 ${count} 份素材，请指定用途与镜头。`);}}
 }catch(error){toast(error.message||'无法读取文件。','error');if(el.type==='file')el.value='';}});
document.addEventListener('focusin',e=>{if(e.target.matches('[data-bind]'))lastEdit='';});
document.addEventListener('dragstart',e=>{const handle=e.target.closest('.drag-handle');if(handle){dragIndex=Number(handle.dataset.index);e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(dragIndex));handle.closest('.shot-card').classList.add('dragging');}});
document.addEventListener('dragover',e=>{const dz=e.target.closest('#import-dropzone');if(dz){e.preventDefault();dz.classList.add('dragover');return;}const card=e.target.closest('.shot-card');if(card&&dragIndex!==null){e.preventDefault();$$('.drop-target').forEach(x=>x.classList.remove('drop-target'));card.classList.add('drop-target');}});
document.addEventListener('dragleave',e=>{const dz=e.target.closest('#import-dropzone');if(dz&&!dz.contains(e.relatedTarget))dz.classList.remove('dragover');});
document.addEventListener('drop',async e=>{const dz=e.target.closest('#import-dropzone');if(dz){e.preventDefault();dz.classList.remove('dragover');const file=e.dataTransfer?.files?.[0];if(file)try{await applyImportedFile(file);}catch(err){toast(err.message||'无法读取文件。','error');}return;}const card=e.target.closest('.shot-card');if(card&&dragIndex!==null){e.preventDefault();moveShot(dragIndex,Number(card.dataset.shotIndex));dragIndex=null;}});
document.addEventListener('dragend',()=>{dragIndex=null;$$('.drop-target,.dragging').forEach(x=>x.classList.remove('drop-target','dragging'));});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('menu-open','preview-open');return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();persist();toast('正在保存项目。');}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!e.target.matches('input,textarea,[contenteditable]')){e.preventDefault();$(`[data-action="${e.shiftKey?'redo':'undo'}"]`)?.click();}});
window.addEventListener('pagehide',()=>{if(p&&!transientProject)DB.saveProject(M.clone(p)).catch(()=>{});});
async function init(){let loadError=null;try{const id=DB.lastProject(),loaded=id?await DB.loadProject(id):null;transientProject=!loaded;p=loaded?M.validateImport(loaded):M.makeBlankProject();if(transientProject)saveStatus='空白项目 · 尚未保存';}catch(e){p=M.makeBlankProject();transientProject=true;saveFailed=true;saveStatus='本地项目加载失败';loadError=e;}view=resumeView();render();loadCreationServices();if(loadError)toast('本地项目暂时无法加载。已有记录保留，可尝试导入项目备份。','error');else await persist();}
init();

function legacyAttributeField(path,key,label,disabled){if(!ATTRIBUTES[key])return input(path,label,{disabled});const current=get(p,path)||'',choices=[...ATTRIBUTES[key]];if(current&&!choices.includes(current))choices.unshift(current);return '<label class="field"><span>'+label+'</span><select aria-label="'+label+'" data-bind="'+path+'" data-attribute="true" '+(disabled?'disabled':'')+'><option value="">未选择</option>'+choices.map(x=>'<option '+(current===x?'selected':'')+' value="'+esc(x)+'">'+esc(x)+'</option>').join('')+'<option value="__custom">自定义…</option></select></label>';}
function commerceView(){p.commerce??=commerceDefaults();const c=p.commerce;return heading('COMMERCE STUDIO / 电商创作','让商品，成为画面主角。','从真实商品与卖点开始，选择主图、场景图或带货视频。',btn('navigate','管理商品参考','layers','btn subtle','data-view="references"'))+panel('商品与任务','<div class="grid two">'+input('commerce.name','商品名称',{placeholder:'填写你的商品'})+select('commerce.category','品类',['','服装配饰','美妆护肤','食品饮料','家居日用','数码家电','运动户外','其他'])+select('commerce.output','输出类型',[['image','商品图片提示词'],['video','广告视频提示词'],['plan','广告分段脚本']])+select('commerce.goal','素材任务',['','白底主图','生活方式场景图','材质细节图','开箱展示','UGC使用演示','问题 → 解决方案','商品揭示广告'])+input('commerce.material','材质')+input('commerce.color','颜色与外观')+input('commerce.audience','目标人群')+select('commerce.platform','投放渠道',['','淘宝 / 天猫','京东','抖音 / 视频号','小红书','Amazon','TikTok Shop','Instagram / Reels'])+'</div>'+input('commerce.sellingPoints','真实卖点',{area:true,placeholder:'只填写已经确认的功能、特性和优势'})+input('commerce.evidence','演示依据',{placeholder:'可拍摄的结构、使用步骤或已验证数据'})+select('commerce.referenceId','商品外观参考',[['','未选择'],...p.references.filter(r=>r.type==='image').map(r=>[r.id,r.name])])+toggle('commerce.preserve','锁定商品外观','保留形状、包装、颜色与标识，不添加未确认信息。'))+panel('展示语言','<div class="grid two">'+select('commerce.scene','展示场景',['','纯白无缝背景','简约摄影棚','木质桌面','家庭厨房','浴室洗手台','户外自然场景','城市生活场景'])+select('commerce.lighting','商品打光',['','大型柔光，控制反射','侧逆光，突出轮廓','侧光，突出材质','自然窗光','高调明亮','低调重点照明'])+select('commerce.composition','商品构图',['','单品居中，完整展示','三分构图，留出文案空间','手持展示，比例自然','微距材质特写','俯拍平铺','使用中的真实比例'])+select('commerce.camera','运镜',['','固定观察','缓慢推进细节','围绕商品90°','商品转台360°','跟随使用动作'])+select('commerce.hook','开场方式',['','痛点提问','先展示真实结果','场景代入','开箱揭示','使用前后对照（需真实依据）'])+select('commerce.cta','收尾引导',['','查看商品详情','了解适用场景','收藏使用方法','选择合适规格'])+'</div>'+input('commerce.copy','指定画内文案',{placeholder:'逐字填写希望出现的文字；留空则不添加'}))+(c.output==='image'?'':panel('广告时间段','<div class="commerce-actions">'+btn('commerce-structure','建立 3 / 7 / 5 秒结构','layers','btn subtle')+btn('commerce-add-beat','添加分段','plus','btn subtle')+'</div>'+c.beats.map((b,i)=>'<div class="commerce-beat"><div class="grid three">'+input('commerce.beats.'+i+'.title','阶段名称')+input('commerce.beats.'+i+'.start','开始 / 秒',{type:'number',min:0,step:.5})+input('commerce.beats.'+i+'.end','结束 / 秒',{type:'number',min:0,step:.5})+'</div>'+input('commerce.beats.'+i+'.action','本段展示什么',{area:true})+input('commerce.beats.'+i+'.voice','本段口播')+btn('commerce-delete-beat','删除分段','trash','text-btn danger','data-index="'+i+'"')+'</div>').join('')))+hint('按你提供的事实整理提示词，不自动编造功效、价格、折扣或测试数据。图片与视频生成需在生成平台完成。')+panel('电商方法参考',COMMERCE_SOURCES.map(([name,desc,url])=>'<a class="commerce-source" href="'+url+'" target="_blank" rel="noopener noreferrer">'+name+' · '+desc+'</a>').join(''));}

function attributeField(path,key,label,disabled){return input(path,label,{disabled});}
function renderMain(){const scroll=$('#main')?.scrollTop||0;closeSuggestions();renderMainBase();enhanceMain();restoreEditorScroll($('#main'),scroll);}
function restoreEditorScroll(element,top){if(!element)return;const behavior=element.style.scrollBehavior;element.style.scrollBehavior='auto';element.scrollTop=top;element.style.scrollBehavior=behavior;}
function presetBar(kind){const list=PRESETS[kind]||[];if(!list.length)return '';const indices=({style:[0,1,2,3,4,5],characters:[0,1,10],scenes:[0,1,6],camera:[0,1,5],performance:[0,1,2],commerce:[0,1,2]})[kind]||[0,1,2],target=presetTarget(kind);const subtitle=entry=>{const d=entry.data;return kind==='style'?[M.label(p,'look',d.look),M.label(p,'color',d.color)].join(' · '):kind==='characters'?[d.gender||'人物',d.outfit?.split('，')[0]].filter(Boolean).join(' · '):kind==='scenes'?[M.label(p,'time',d.time),M.label(p,'weather',d.weather)].join(' · '):kind==='camera'?[M.label(p,'framing',d.framing),M.label(p,'move',d.move)].join(' · '):kind==='performance'?M.label(p,'emotion',d.emotion):d.goal||'商品展示方案';};return `<section class="preset-shelf" aria-label="推荐快捷组合"><div class="preset-shelf-head"><span>${icon('spark')}先选一种感觉<small>组合可继续细调</small></span><select aria-label="${({style:'影像质感',characters:'人物',scenes:'场景光线',camera:'摄影运镜',performance:'表演声音',commerce:'电商'})[kind]}快捷组合" data-ui="preset-${kind}"><option value="">全部 ${list.length} 套组合…</option>${list.map((x,i)=>`<option value="${i}">${esc(x.name)}</option>`).join('')}</select></div><div class="featured-presets">${indices.filter(i=>list[i]).map(i=>{const x=list[i],active=Object.entries(x.data).every(([k,v])=>JSON.stringify(target[k])===JSON.stringify(v));return `<button type="button" data-action="preview-preset" data-kind="${kind}" data-index="${i}" class="featured-preset ${active?'selected':''}" aria-label="预览组合：${esc(x.name)}"><span class="preset-swatch"></span><strong>${esc(x.name)}</strong><small>${esc(subtitle(x))}</small></button>`;}).join('')}</div></section>`;}
function enhanceMain(){const aiIdea=document.querySelector('[data-bind="aiBrief.idea"]');if(aiIdea)aiIdea.maxLength=100000;const videoIdea=document.querySelector('[data-bind="videoDraft.prompt"]');if(videoIdea)videoIdea.maxLength=100000;
 const heading=$('#main .page-heading');if(heading&&PRESETS[view])heading.insertAdjacentHTML('afterend',presetBar(view));if(heading&&p.mode!=='commerce'&&view!=='start')heading.insertAdjacentHTML('beforebegin',workflowMarkup(p,view));refineEditor();decorateTextareas();renderJourneyFooter();
 if(assetFlow&&heading)heading.insertAdjacentHTML('afterend',`<div class="asset-flow-banner"><span>${icon('arrow')}正在添加${assetFlow.label}<small>保存后回到原来的选择位置</small></span>${btn('finish-asset-flow','完成并返回'+(assetFlow.shotId?'分镜':'原页面'),'check','btn primary small')}</div>`);
 for(const el of $$('textarea[data-bind]', $('#main'))){if(!el.closest('.editable-control')&&suggestionsFor(el.dataset.bind).length){el.insertAdjacentHTML('afterend',`<div class="textarea-examples">${btn('show-suggestions','参考示例','chevron','text-btn',`data-path="${el.dataset.bind}" aria-label="${esc(el.getAttribute('aria-label')||'内容')}预选示例" aria-expanded="false" aria-haspopup="listbox"`)}</div>`);}}
}

function closeSuggestions(){document.getElementById('suggestion-layer')?.remove();if(suggestionState?.trigger?.isConnected)suggestionState.trigger.setAttribute('aria-expanded','false');suggestionState=null;}
function openSuggestions(path,trigger){
 if(suggestionState?.path===path){closeSuggestions();return;}closeSuggestions();const control=Array.from(document.querySelectorAll('[data-bind]')).find(x=>x.dataset.bind===path&&x.closest('#main'));if(!control||control.disabled)return;
 const values=[...new Set([...(FIELD_EXAMPLES.get(path)||[]),...suggestionsFor(path,control.getAttribute('aria-label')||'')])];if(!values.length)return;const box=document.createElement('div');box.id='suggestion-layer';box.className='suggestion-menu';box.setAttribute('role','listbox');box.setAttribute('aria-label','预选示例');box.innerHTML=`<div class="suggestion-heading">可选示例 · 选择后仍可改写</div>${values.map((v,i)=>`<button type="button" role="option" aria-selected="${control.value===v}" data-action="choose-suggestion" data-path="${path}" data-index="${i}" title="${esc(v)}">${esc(v)}</button>`).join('')}<div class="suggestion-foot">不合适？直接在输入框里填写。</div>`;
 document.body.append(box);const rect=control.getBoundingClientRect(),width=Math.min(Math.max(rect.width,280),420,window.innerWidth-24),height=Math.min(box.scrollHeight,300),below=window.innerHeight-rect.bottom-12;box.style.width=width+'px';box.style.left=Math.max(12,Math.min(rect.left,window.innerWidth-width-12))+'px';box.style.top=(below>=Math.min(height,150)?rect.bottom+5:Math.max(8,rect.top-height-5))+'px';box.style.maxHeight=Math.max(130,below>=150?Math.min(300,below):Math.min(300,rect.top-14))+'px';suggestionState={path,values,control,trigger};trigger.setAttribute('aria-expanded','true');
}
function chooseSuggestion(path,index){if(!suggestionState||suggestionState.path!==path)return;const {values,control}=suggestionState,value=values[index];if(value===undefined)return;remember();set(p,path,value);control.value=value;closeSuggestions();if(path.startsWith('aiBrief.'))updateAIBriefControls();changed();control.focus({preventScroll:true});}
document.addEventListener('pointerdown',e=>{if(suggestionState&&!e.target.closest('#suggestion-layer,[data-action="show-suggestions"]'))closeSuggestions();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeSuggestions();if(e.key==='ArrowDown'&&e.target.matches('input[data-bind],textarea[data-bind]')&&suggestionsFor(e.target.dataset.bind).length){e.preventDefault();const trigger=e.target.parentElement.querySelector('[data-action="show-suggestions"]')||e.target.parentElement.querySelector('.textarea-examples button');if(trigger){openSuggestions(e.target.dataset.bind,trigger);$('#suggestion-layer [role="option"]')?.focus();}}else if(suggestionState&&e.target.closest('#suggestion-layer')&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const rows=$$('#suggestion-layer [role="option"]'),i=rows.indexOf(e.target);rows[(i+(e.key==='ArrowDown'?1:-1)+rows.length)%rows.length]?.focus();}});
document.addEventListener('scroll',e=>{if(suggestionState&&!e.target.closest?.('#suggestion-layer'))closeSuggestions();},true);
window.addEventListener('resize',closeSuggestions);
function startAssetFlow(path){
 const relation=relationFor(path);if(!relation)return;const oldView=view,originShot=/^shots\.(\d+)\./.exec(path),shot=originShot?p.shots[Number(originShot[1])]:null;remember();assetFlow={...relation,path,fromView:oldView,shotId:shot?.id||null,scroll:$('#main')?.scrollTop||0};
 if(relation.kind==='scenes'){const asset=M.blankScene();p.scenes.push(asset);sceneSelected=p.scenes.length-1;set(p,path,asset.id);}
 if(relation.kind==='characters'){const asset=M.blankCharacter('角色'+String.fromCharCode(65+p.characters.length));p.characters.push(asset);castSelected=p.characters.length-1;if(path.endsWith('.characterIds'))set(p,path,[...(get(p,path)||[]),asset.id]);else set(p,path,asset.id);characterGroup='basic';}
 if(relation.kind==='props'){const asset={id:M.uid(),name:'新道具',appearance:'',ownerId:''};p.props.push(asset);set(p,path,asset.id);}
 view=relation.view;changed({refresh:true});$('#main').scrollTop=0;if(relation.kind==='props'){document.querySelector('[data-bind="props.'+(p.props.length-1)+'.name"]')?.closest('.panel')?.scrollIntoView({block:'start'});}
}
function finishAssetFlow(){if(!assetFlow)return;const flow=assetFlow;if(flow.kind==='cameraTemplates'){const t=cameraTemplates().find(x=>x.id===p.cameraDraftId),shot=p.shots.find(x=>x.id===flow.shotId);if(!t){toast('请先保存一套摄影预选。');return;}if(shot){remember();applyCameraTemplate(p,shot,t);changed();}}assetFlow=null;if(flow.shotId){const i=p.shots.findIndex(s=>s.id===flow.shotId);if(i>=0)selected=i;}view=flow.fromView;render();$('#main').scrollTop=flow.scroll;const field=Array.from(document.querySelectorAll('#main [data-bind]')).find(x=>x.dataset.bind===flow.path);field?.focus({preventScroll:true});toast('已带回选择，继续编辑即可。');}
function presetList(kind){return kind==='faces'?ALL_FACES.map(({name,...data})=>({name,data})):PRESETS[kind]||[];}
function presetTarget(kind,create=false){
 if(kind==='style')return p.style;if(kind==='camera'){p.cameraDraft??=M.clone(p.camera);return p.cameraDraft;}if(kind==='commerce'){p.commerce??=commerceDefaults();return p.commerce;}
 if(kind==='characters'||kind==='faces'){if(!p.characters.length&&create){p.characters.push(M.blankCharacter('角色A'));castSelected=0;}return p.characters[castSelected]||{};}
 if(kind==='scenes'){if(!p.scenes.length&&create){p.scenes.push(M.blankScene());sceneSelected=0;}return p.scenes[sceneSelected]||{};}
 if(kind==='performance'){if(!p.shots.length&&create){const s=M.makeShot(p);if(p.fromScratch){s.emotion='';s.music='';s.purpose='';s.intensity='';}p.shots.push(s);selected=0;}return p.shots[selected]||{};}
 return {};
}
function presetFieldLabel(key,kind){if(key==='name')return kind==='scenes'?'场景名称':kind==='commerce'?'商品名称':'姓名 / 代号';return GROUPS[key]?.label||Object.fromEntries(CHARACTER_FIELDS)[key]||Object.fromEntries(SCENE_FIELDS)[key]||({lightNote:'材质上的光线',orbit:'环绕角度',direction:'俯视方向',subjectTurn:'人物转身',focusFrom:'起点焦点',focusTo:'终点焦点',intensity:'表演强度',audio:'音效',music:'配乐',dialogueLanguage:'台词语言',preserve:'保持商品外观',output:'输出类型',goal:'素材任务',lighting:'商品打光',camera:'商品运镜',hook:'开场方式',cta:'收尾引导',category:'品类',composition:'构图'})[key]||key;}
function presetValue(key,value){if(Array.isArray(value))return value.map(x=>GROUPS[key]?M.label(p,key,x):x).join('、');if(GROUPS[key])return M.label(p,key,value);if(typeof value==='boolean')return value?'是':'否';if(key==='output')return ({image:'商品图片提示词',video:'广告视频提示词',plan:'广告分段脚本'})[value]||value;if(key==='direction')return value==='cw'?'顺时针':'逆时针';return String(value);}
function openPreset(kind,index,emptyOnly=false){
 const entry=presetList(kind)[index];if(!entry)return;activePreset={kind,index,emptyOnly};const target=presetTarget(kind),plan=planPreset(target,entry.data,{character:['characters','faces'].includes(kind),emptyOnly});
 modal('快捷组合 · '+esc(entry.name),`<p class="help">确认后仅填入下表列出的字段，其他设定保留。可继续选择示例或自由改写。</p><label class="preset-empty-toggle"><input type="checkbox" data-ui="preset-empty" ${emptyOnly?'checked':''}>只填空白字段</label><div class="preset-change-list">${plan.changes.map(({key,value})=>`<div><strong>${esc(presetFieldLabel(key,kind))}</strong><span>${esc(presetValue(key,value))}</span></div>`).join('')||'<p class="help">没有可更新字段：可能已经相同，或相关字段已锁定。</p>'}</div>${plan.skipped.length?hint('保留：'+plan.skipped.map(x=>esc(presetFieldLabel(x.key,kind))+'（'+x.reason+'）').join('、')):''}${['characters','faces','scenes','performance'].includes(kind)&&Object.keys(target).length===0?hint('将先添加一个空白'+({characters:'角色',faces:'角色',scenes:'场景',performance:'镜头'})[kind]+'，再填入本套选项。'):''}`,btn('close-modal','取消','','btn subtle')+btn('apply-quick-preset','确认填入','check','btn primary',plan.changes.length?'':'disabled'),'quick-preset');
}
function applyQuickPreset(){if(!activePreset)return;const {kind,index,emptyOnly}=activePreset,entry=presetList(kind)[index];if(!entry)return;remember();const target=presetTarget(kind,true),plan=planPreset(target,entry.data,{character:['characters','faces'].includes(kind),emptyOnly});for(const {key,value} of plan.changes)target[key]=M.clone(value);if(kind==='camera')p.cameraDraftName=entry.name;const usageKey='preset:'+kind+':'+index;prefs.usage[usageKey]={count:(prefs.usage[usageKey]?.count||0)+1,time:Date.now()};persistPrefs();closeModal();changed({refresh:true});toast(`已填入“${entry.name}”，${plan.skipped.length?'锁定或已有字段保留。':'可继续修改。'}`);}

function cameraTemplates(){return (prefs.cameraTemplates||[]).filter(x=>x&&typeof x.id==='string'&&typeof x.name==='string'&&x.camera);}
function cameraLibraryPanel(){const list=cameraTemplates(),editing=list.some(x=>x.id===p.cameraDraftId);return panel('我的摄影预选',`<div class="camera-library-tools"><label class="field"><span>已保存预选 <small>${list.length}套</small></span><select aria-label="已保存摄影预选" data-ui="load-camera-draft"><option value="">${list.length?'选择一套继续编辑…':'尚未保存，先编辑下面的设置'}</option>${list.map(x=>`<option value="${x.id}" ${p.cameraDraftId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>${input('cameraDraftName','预选名称',{placeholder:'例如：缓推情绪近景'})}<div class="camera-save-buttons">${btn('save-camera-template',editing?'更新当前预选':'保存为新预选','check','btn primary small')}${editing?btn('save-camera-copy','另存新预选','copy','btn subtle small'):''}${editing?btn('delete-camera-template','删除预选','trash','text-btn danger',`data-id="${p.cameraDraftId}"`):''}</div></div>${list.length?'<p class="help">预选保存在当前浏览器，可跨项目选用。分镜复制所选设置，保留独立调整。</p>':''}`);}
function cameraPresetSelector(shot,index){const list=cameraTemplates(),builtin=PRESETS.camera.map((x,i)=>({...x,id:'builtin:'+i})),current=[...list,...builtin].some(x=>x.id===shot.cameraPresetId);return `<label class="shot-camera-preset"><span>摄影预选</span><select aria-label="镜头${index+1}摄影预选" data-ui="shot-camera-preset" data-index="${index}"><option value="">${current?'选择其他预选…':shot.cameraPresetName?esc(shot.cameraPresetName)+' · 镜头副本':Object.keys(shot.camera||{}).length?'本镜手动设置':'继承全局 / 未选预选'}</option>${list.length?'<optgroup label="我的摄影预选">'+list.map(x=>`<option value="${x.id}" ${x.id===shot.cameraPresetId?'selected':''}>${esc(x.name)}</option>`).join('')+'</optgroup>':''}<optgroup label="内置摄影方案">${builtin.map(x=>`<option value="${x.id}" ${x.id===shot.cameraPresetId?'selected':''}>${esc(x.name)}</option>`).join('')}</optgroup><option value="__create__">＋ 编辑并保存自己的预选</option></select></label>`;}
function openCameraLibraryForShot(shot){if(!shot)return;assetFlow={kind:'cameraTemplates',label:'摄影预选',fromView:view,shotId:shot.id,path:'',scroll:$('#main').scrollTop};view='camera';p.cameraDraft??=M.camera(p,shot);render();$('#main').scrollTop=0;}
function loadCameraDraft(id){const t=cameraTemplates().find(x=>x.id===id);if(!t)return;remember();mergeCameraCatalog(p,t);p.cameraDraft=M.clone(t.camera);p.cameraDraftName=t.name;p.cameraDraftId=t.id;orderCache={};changed({refresh:true});}
function saveCameraDraft(copy){try{const old=M.clone(prefs.cameraTemplates||[]),existing=cameraTemplates().find(x=>x.id===p.cameraDraftId),id=!copy&&existing?existing.id:M.uid(),template=makeCameraTemplate(p,p.cameraDraftName,p.cameraDraft||p.camera,id);prefs.cameraTemplates??=[];const index=prefs.cameraTemplates.findIndex(x=>x.id===id);if(index<0)prefs.cameraTemplates.push(template);else prefs.cameraTemplates[index]=template;if(!persistPrefs()){prefs.cameraTemplates=old;return;}remember();p.cameraDraftId=id;changed({refresh:true});toast(`已保存“${template.name}”，可在单个镜头中选择。`);}catch(e){toast(e.message,'error');}}
function requestCameraTemplateDeletion(id){const t=cameraTemplates().find(x=>x.id===id);if(!t)return;modal('删除摄影预选？',`<p>将删除“${esc(t.name)}”。已经选用它的镜头保留自己的设置副本。</p>`,btn('close-modal','取消','','btn subtle')+btn('confirm-delete-camera-template','确认删除','trash','btn danger-fill',`data-id="${id}"`));}
function deleteCameraTemplate(id){const old=M.clone(prefs.cameraTemplates||[]);prefs.cameraTemplates=old.filter(x=>x.id!==id);if(!persistPrefs()){prefs.cameraTemplates=old;return;}if(p.cameraDraftId===id)delete p.cameraDraftId;closeModal();render();toast('预选已删除，已有镜头设置保留。');}

function decorateTextareas(){for(const el of $$('#main textarea[data-bind]')){const path=el.dataset.bind;el.id='edit-'+path.replace(/[^a-zA-Z0-9-]/g,'-');const container=el.closest('.field')||el.closest('.end-state')||el.parentElement;const header=container.querySelector('.field-label,:scope>span:first-child,.state-line');if(header&&!header.querySelector('.textarea-toggle'))header.insertAdjacentHTML('beforeend',btn('toggle-textarea',expandedTextAreas.has(path)?'收回':'展开','chevron','textarea-toggle',`data-path="${path}" aria-label="${expandedTextAreas.has(path)?'收回':'展开'}${esc(el.getAttribute('aria-label')||'文本')}" aria-expanded="${expandedTextAreas.has(path)}" aria-controls="${el.id}"`));fitTextarea(el);}}
function fitTextarea(el){if(!el?.matches('textarea[data-bind]'))return;const expanded=expandedTextAreas.has(el.dataset.bind);el.classList.toggle('expanded-textarea',expanded);el.rows=2;if(expanded){el.style.setProperty('--expanded-height','auto');el.style.setProperty('--expanded-height',Math.min(360,Math.max(120,el.scrollHeight+4))+'px');}const button=el.closest('.field,.end-state')?.querySelector('.textarea-toggle');if(button){button.innerHTML=icon('chevron')+(expanded?'收回':'展开');button.setAttribute('aria-expanded',String(expanded));button.setAttribute('aria-label',(expanded?'收回':'展开')+(el.getAttribute('aria-label')||'文本'));}}
function toggleTextarea(path){const el=Array.from(document.querySelectorAll('#main textarea[data-bind]')).find(x=>x.dataset.bind===path);if(!el)return;const top=$('#main').scrollTop;if(expandedTextAreas.has(path))expandedTextAreas.delete(path);else expandedTextAreas.add(path);fitTextarea(el);restoreEditorScroll($('#main'),top);}

async function projectsModal(){await persist();projects=(await DB.listProjects()).sort((a,b)=>b.updatedAt-a.updatedAt);modal('我的项目',`<div class="projects-heading"><span>${projects.length} 个本地项目</span>${btn('clear-projects','一键清空','trash','text-btn danger',projects.length?'':'disabled')}</div><div class="project-list">${projects.map(x=>`<div class="project-manager-row"><button data-action="open-project" data-id="${x.id}"><span class="project-icon">${icon('film')}</span><span><strong>${esc(x.title)}</strong><small>${x.shots.length}镜 · ${M.fmt(M.totalDuration(x))}秒 · ${new Date(x.updatedAt).toLocaleString('zh-CN')}</small></span>${x.id===p.id?'<em>当前</em>':icon('chevron')}</button>${btn('delete-listed-project','','trash','icon-btn danger',`data-id="${x.id}" title="删除项目" aria-label="删除项目${esc(x.title)}"`)}</div>`).join('')||'<div class="small-empty">暂无保存的项目。从零开始或选择模板创建。</div>'}</div>`,btn('import','导入项目','upload','btn subtle')+btn('new-project','新建项目','plus','btn primary'));}
async function requestProjectDeletion(id){await persist();const list=await DB.listProjects(),project=id?list.find(x=>x.id===id):null;if(id&&!project){toast('当前项目尚未保存，或已经删除。');return;}if(!id&&!list.length){toast('没有需要清空的项目。');return;}pendingProjectDeletion={id,all:!id};const title=id?'删除这个项目？':'清空所有本地项目？';modal(title,id?`<p>将删除“${esc(project.title)}”及其项目内参考文件。此操作不能通过编辑撤销恢复。</p>`:`<p>将清空当前浏览器中的 <strong>${list.length}</strong> 个项目及项目内参考文件。公共角色模板、摄影预选和偏好保留。</p><p class="help">此操作不能通过编辑撤销恢复，请确认已有需要的备份。</p>`,btn('projects','取消，返回项目列表','','btn subtle')+btn('confirm-project-deletion',id?'确认删除项目':'确认清空所有项目','trash','btn danger-fill'));}
async function confirmProjectDeletion(){const task=pendingProjectDeletion;if(!task)return;clearTimeout(saveTimer);await persist();if(task.all)await DB.clearProjects();else await DB.deleteProject(task.id);pendingProjectDeletion=null;revision++;if(task.all||task.id===p.id){const rest=(await DB.listProjects()).sort((a,b)=>b.updatedAt-a.updatedAt);p=rest[0]||M.makeBlankProject();transientProject=!rest.length;if(transientProject){p.createdAt=Date.now()+1;DB.clearLastProject();saveStatus='空白项目 · 尚未保存';}else{DB.lastProject(p.id);saveStatus='已保存到本地';}selected=castSelected=sceneSelected=0;undo=[];redo=[];expandedShots.clear();expandedTextAreas.clear();assetFlow=null;activePreset=null;view=p.mode==='commerce'?'commerce':'storyboard';render();}await projectsModal();toast(task.all?'所有本地项目已清空。':'项目已删除。');}

function updateSurface(next,replace=false){surface=next;const hash=next==='home'?'#home':'#workbench';if(location.hash!==hash)history[replace?'replaceState':'pushState'](null,'',hash);}
function resumeView(){const valid=['start','characters','style','scenes','performance','storyboard','camera','references','specs','commerce','ai','video','connections'],last=prefs.lastViews?.[p.id];if(p.mode==='commerce')return 'commerce';return hasCreativeContent(p)&&valid.includes(last)&&last!=='commerce'?last:hasCreativeContent(p)?suggestedView(p):'start';}
function enterStudio(){updateSurface('studio');view=resumeView();document.body.classList.remove('menu-open','preview-open');render();$('#main').scrollTop=0;}
async function newCreativeProject(kind){const next=M.makeBlankProject();if(kind==='commerce'){next.mode='commerce';next.commerce.output='video';next.title='未命名商品项目';commerceGroup='product';}await changeProject(next);view=kind==='commerce'?'commerce':'start';renderMain();$('#main').scrollTop=0;}
function navigateToView(next){if(!['start','characters','style','scenes','performance','storyboard','camera','references','specs','commerce','ai','video','connections'].includes(next))return;closeSuggestions();if(surface!=='studio')updateSurface('studio');view=next==='start'&&p.mode==='commerce'?'commerce':next;orderCache={};search='';prefs.lastViews??={};prefs.lastViews[p.id]=view;const ids=Object.keys(prefs.lastViews);if(ids.length>100)delete prefs.lastViews[ids[0]];persistPrefs();document.body.classList.remove('menu-open');render();$('#main').scrollTop=0;}
function startView(){return heading('YOUR FIRST SCENE / 创作起点','先记住，你想拍的那一幕。','一句话就够了。人物、光线和镜头，接下来慢慢选择。','')+`<section class="brief-box"><div class="eyebrow">一切，从一个念头开始</div>${input('logline','这一幕，你想讲什么？',{area:true,placeholder:'例如：分别多年后，她在即将关门的咖啡馆听见了那个熟悉的声音。'})}<div class="idea-seeds"><span>还没想好？试试</span>${IDEA_SEEDS.map((x,i)=>btn('idea-seed',x.label,'spark','',`data-index="${i}"`)).join('')}</div><div class="brief-actions">${btn('open-ai','AI帮我填写','spark','btn primary','data-use-idea="true"')}${btn('navigate','开始设定人物','arrow','btn subtle','data-view="characters"')}${btn('templates','也可以，从一套模板开始','','text-btn')}</div><p class="brief-caption">你写下的内容会实时汇入右侧；不必现在就把整个故事想完整。</p></section><div class="start-map">${workflowSteps(p).map((x,i)=>`<button data-action="navigate" data-view="${x.id}"><span>0${i+1}</span><strong>${x.verb}</strong><small>${x.help}</small></button>`).join('')}</div><div class="start-note">${icon('film')}<div>先完成一小段，再把它变得更好。<p>快速制作会突出常用设定。需要五官、轴线、对白时间和复杂调度时，再展开详细设置或切换导演模式。</p></div></div>`;}
function emptyPromptMarkup(){return `<div class="empty-prompt"><div class="empty-prompt-path"><span>${icon('person')}</span><i></i><span>${icon('scene')}</span><i></i><span>${icon('board')}</span></div>你的画面，会在这里成形。<small>写下一句想法，或选择一个人物。<br>每一个选择，都会让提示词更完整。</small>${btn('navigate','从创作起点开始','arrow','text-btn','data-view="start"')}</div>`;}
function disclosure(id,title,body){return `<details class="progressive-details" data-ui-detail="${esc(id)}" ${openDetails.has(id)?'open':''}><summary>${esc(title)}</summary><div class="disclosure-body">${body}</div></details>`;}
function wrapOptional(nodes,id,title){nodes=nodes.filter(Boolean);if(!nodes.length)return null;const d=document.createElement('details');d.className='progressive-details';d.dataset.uiDetail=id;d.open=openDetails.has(id);d.innerHTML=`<summary>${esc(title)}</summary><div class="disclosure-body"></div>`;nodes[0].before(d);const body=d.lastElementChild;nodes.forEach(node=>body.append(node));return d;}
function refineEditor(){
 const root=$('#main');if(!root)return;
 // Five-feature presets belong with face editing; keep the basic identity page calm.
 if(view==='characters'){const faces=$('.face-presets',root);if(faces)faces.hidden=characterGroup!=='face'&&characterGroup!=='all';}
 if(view==='camera')wrapOptional([$('.motion-demo',root)],'camera-diagram','查看运镜示意');
 if(p.mode!=='quick')return;
 const panels=$$('.panel',root),byTitle=title=>panels.find(x=>$('h3',x)?.textContent===title);
 if(view==='characters'){
  const locks=$('.lock-grid',root),c=p.characters[castSelected],locked=c&&Object.values(c.locks).some(Boolean);
  wrapOptional([locks],'character-locks','一致性保护与锁定'+(locked?' · 已有锁定项':''));
  wrapOptional([$('.panel-footer',byTitle('角色档案')||root)],'character-manage','保存模板、造型版本与角色管理');
  wrapOptional([byTitle('关键道具')],'character-props','关键道具 · 按需添加');
 }
 if(view==='style'){
  const main=byTitle('画面风格');if(main){const d=wrapOptional($$(':scope > .picker',main).filter(x=>$('[data-picker-key="medium"],[data-key="texture"]',x)),'style-material','影像介质与细节纹理');if(d)main.append(d);}
  wrapOptional([byTitle('补充你的视觉描述')],'style-notes','补充自己的质感描述');
 }
 if(view==='scenes'){
  const grid=$('.scene-fields',root);if(grid){const optional=$$('.field',grid).filter(x=>{const path=$('[data-bind]',x)?.dataset.bind||'';return !/\.(name|description)$/.test(path);});const details=wrapOptional(optional,'scene-environment','环境细节 · 前景、背景、动态与声音');if(details){grid.after(details);details.lastElementChild.classList.add('scene-detail-fields');}}
  const light=byTitle('有动机的光影');if(light)wrapOptional($$(':scope > .picker,:scope > .field',light).filter(x=>!$('[data-picker-key="lightSource"]',x)),'scene-light','细调光向、软硬与材质反馈');
 }
 if(view==='performance'){
  const acting=byTitle('细腻表演');if(acting)wrapOptional($$(':scope > .picker',acting).filter(x=>$('[data-key="micro"]',x)),'performance-micro','微表演 · 视线、呼吸与手部细节');
  const voice=byTitle('对白与声音'),grid=voice&&$('.grid',voice);if(grid){const extra=$$(':scope > .field',grid).slice(3),estimate=$('#dialogue-estimate',voice),details=wrapOptional(extra,'performance-timing','对白时间与语速');if(details){grid.after(details);if(estimate)details.lastElementChild.append(estimate);}}
  wrapOptional([byTitle('镜内时序')],'performance-segments','细分到每几秒 · 可选');
 }
}
function renderJourneyFooter(){const mount=$('#journey-footer');if(!mount)return;mount.innerHTML=nextStepMarkup(p,view,commerceGroup);const bar=$('.workspace-next',mount);if(bar)bar.insertAdjacentHTML('afterbegin',btn('toggle-preview','提示词预览','eye','btn subtle journey-preview'));}
function updateJourney(){if(surface!=='studio')return;if(view==='video'){const timing=$('#video-timing-hint');if(timing)timing.textContent=videoTimingText();}const rail=$('.workflow-rail');if(rail)rail.outerHTML=workflowMarkup(p,view);renderJourneyFooter();}
document.addEventListener('toggle',e=>{const d=e.target;if(!d.matches?.('details[data-ui-detail]'))return;d.open?openDetails.add(d.dataset.uiDetail):openDetails.delete(d.dataset.uiDetail);},true);
window.addEventListener('popstate',()=>{if(!p)return;surface=location.hash.startsWith('#workbench')?'studio':'home';if(surface==='studio'&&(!view||view==='commerce'&&p.mode!=='commerce'))view=hasCreativeContent(p)?suggestedView(p):'start';document.body.classList.remove('menu-open','preview-open');render();});
window.addEventListener('hashchange',()=>{if(!p)return;const next=location.hash.startsWith('#workbench')?'studio':'home';if(next!==surface){surface=next;render();}});


document.addEventListener('input',e=>{const el=e.target,path=el.dataset.aiEdit;if(!path||!p)return;if(!/^(title|logline|shots\.\d+\.(title|duration|action|dialogue))$/.test(path))return;const proposal=aiSuggestion();if(!proposal||proposal.applied)return;remember('ai-suggestion-edit');p.aiSuggestion=M.clone(proposal);const val=el.type==='number'?Number(el.value):el.value;set(p.aiSuggestion.plan,path,val);const m=/^shots\.(\d+)\.(title|duration)$/.exec(path);if(m){const row=document.querySelector(`.ai-preview-shot[data-ai-shot="${m[1]}"]`);if(row){if(m[2]==='title'&&row.querySelector('[data-ai-shot-title]'))row.querySelector('[data-ai-shot-title]').textContent=val||'未命名镜头';if(m[2]==='duration'&&row.querySelector('[data-ai-shot-duration]'))row.querySelector('[data-ai-shot-duration]').textContent=(Number.isFinite(val)?val:0)+'秒';}const meta=$('[data-ai-meta="summary"]');if(meta){const pl=p.aiSuggestion.plan;meta.textContent=`${pl.characters.length} 人物 · ${pl.scenes.length} 场景 · ${pl.shots.length} 镜头 · ${M.fmt(pl.shots.reduce((n,s)=>n+(Number(s.duration)||0),0))}秒`;}}changed();});


function ensureAIData(){const had=!!p.aiBrief;p.aiBrief??={idea:p.logline||'',duration:Math.max(5,Number(p.targetDuration)||20),shotCount:3,reuse:true,autoFill:true,chainLastFrame:!!p.chainLastFrame,cutFrameCheck:!!p.cutFrameCheck};for(const [k,v] of Object.entries(AI_BRIEF_DEFAULTS))if(p.aiBrief[k]===undefined)p.aiBrief[k]=M.clone(v);p.aiBrief.castDefaults={...castProfileDefaults(),...(p.aiBrief.castDefaults||{})};if(!Array.isArray(p.aiBrief.castProfiles)||!p.aiBrief.castProfiles.length)p.aiBrief.castProfiles=[{...castProfileDefaults(),...p.aiBrief.castDefaults},{...castProfileDefaults(),...p.aiBrief.castDefaults}];if(!had){p.aiBrief.chainLastFrame=!!p.chainLastFrame;p.aiBrief.cutFrameCheck=!!p.cutFrameCheck;}p.aiBrief.autoFill??=true;return p.aiBrief;}
function aiContinuityHintText(b){const parts=[];if(b.chainLastFrame)parts.push('已开启【尾帧接下一镜首帧】：提示词【生成阶段规范】将写入一镜一镜按顺序生成、上镜尾帧作下镜输入图、逐秒抽帧检查、防提前演剧情截断、重做后全量重接等 5 条铁律');if(b.cutFrameCheck)parts.push('已开启【切点前后两帧检查】：仅约束生成阶段使上一镜尾帧与下一镜首帧头发/手臂/衣服/位置完全一致（有漂移则生成阶段重修）；后期镜间转场仍严格按文末剪辑执行表无条件执行');return parts.length?parts.join('；')+'。':'可选开启连贯控制：勾选上方开关将同步至分镜工作台与右侧提示词，强制逐镜尾帧续接与生成阶段切点校验；所有转场另行写入【后期合并剪辑与转场执行表】。';}
function aiBgmHintText(b){return {auto:'当前为「AI 自己搭配」：AI 将结合剧情情绪、场景与对白节奏自动设计背景配乐（若下方填写风格/情绪也会纳入参考），并同步填入「表演与声音」。',guided:'当前为「选个大概方向」：AI 将顺着你选择的曲风与情绪方向自由发挥，细化主奏乐器、进出时机与对白压低避让。',exact:'当前为「明确指定配乐」：AI 将严格锁定你上方选择的配乐曲风、情绪与细节要求，不擅自更改风格。',none:'当前为「无背景音乐」：全片不加背景音乐，仅保留真实环境底声、动作音效与人物对白。'}[b.bgmMode||'auto']||'';}
const FIELD_EXAMPLES=new Map();
function dataliChoice(path,id,label,examples,placeholder='可选，也可自己输入'){FIELD_EXAMPLES.set(path,examples);const val=get(p,path)??'';return `<div class="field assist-field"><span class="field-label">${esc(label)}</span><div class="editable-control"><input aria-label="${esc(label)}" data-bind="${path}" value="${esc(val)}" placeholder="${esc(placeholder)}" autocomplete="off">${btn('show-suggestions','','chevron','suggestion-trigger',`data-path="${path}" aria-label="${esc(label)}预选示例" aria-expanded="false" aria-haspopup="listbox"`)}</div></div>`;}
function aiChoice(key,label,examples,placeholder='可选，也可自己输入'){return dataliChoice('aiBrief.'+key,'ai-options-'+key,label,examples,placeholder);}
function aiCastControls(b){
 const allBox=`<div id="ai-cast-all-box"><div class="grid two">${select('aiBrief.castDefaults.nationality','国家 / 民族面孔（全部人物默认）',AI_CAST_NATIONALITIES)}${select('aiBrief.castDefaults.faceTier','颜值档位 / 人物类型（真人/动漫）',AI_CAST_FACE_TIERS)}${select('aiBrief.castDefaults.skinRender','皮肤质感 / 磨皮程度',AI_CAST_SKIN_RENDERS)}${dataliChoice('aiBrief.castDefaults.occupation','ai-cast-occ-all','默认职业倾向',AI_CAST_OCCUPATION_EXAMPLES,'例如：普通上班族 / 医生 / 古风侠客')}</div>${input('aiBrief.castDefaults.notes','全部人物补充外貌要求（可选）',{placeholder:'例如：自然日常穿着，避免过度网红妆感或夸张服饰'})}</div>`;
 aiCastTab=Math.max(0,Math.min(aiCastTab,b.castProfiles.length-1));
 const prof=b.castProfiles[aiCastTab]||castProfileDefaults(),idx=aiCastTab;
 const castTabs=b.castProfiles.map((pr,k)=>{
  const nat=AI_CAST_NATIONALITIES.find(x=>x[0]===pr.nationality)?.[0]||pr.nationality||'待选';
  return [String(k),`0${k+1}`,pr.name||`人物 ${k+1}`,nat];
 });
 const addCastBtn=b.castProfiles.length<20?`<button type="button" class="browser-tab-add" data-action="ai-add-cast-profile" title="新增一位独立控制的人物">${icon('plus')}<span>添加人物</span></button>`:'';
 const activeCard=`<div class="cast-profile-card" data-cast-index="${idx}"><div class="cast-profile-head"><strong>正在编辑 · 人物 ${idx+1}${prof.name?' · '+esc(prof.name):''}</strong><div class="cast-profile-actions">${btn('ai-sync-cast-profiles','套用「全部人物」到空白项','','text-btn')}${b.castProfiles.length>1?btn('ai-remove-cast-profile','','trash','icon-btn',`data-index="${idx}" title="移除该人物槽位" aria-label="移除人物 ${idx+1}"`):''}</div></div><div class="ai-cast-card-grid">${input(`aiBrief.castProfiles.${idx}.name`,'称呼 / 定位',{placeholder:`例如：主角${idx+1} / 陈默 / 美国搭档`})}${select(`aiBrief.castProfiles.${idx}.nationality`,'国家 / 民族面孔',AI_CAST_NATIONALITIES)}${select(`aiBrief.castProfiles.${idx}.faceTier`,'颜值档位 / 人物类型',AI_CAST_FACE_TIERS)}${select(`aiBrief.castProfiles.${idx}.skinRender`,'皮肤质感 / 磨皮程度',AI_CAST_SKIN_RENDERS)}${dataliChoice(`aiBrief.castProfiles.${idx}.occupation`,`ai-cast-occ-${idx}`,'职业 / 身份',AI_CAST_OCCUPATION_EXAMPLES,'例如：咖啡师 / 程序员 / 外企高管')}${input(`aiBrief.castProfiles.${idx}.notes`,'外貌补充（可选）',{placeholder:'例如：戴黑框眼镜，短发，自然雀斑'})}</div></div>`;
 const indivBox=`<div id="ai-cast-individual-box"><section class="web-tabs-shell compact-web-tabs">${webTabBar('ai-cast-tab',aiCastTab,castTabs,addCastBtn)}<div class="web-tab-panel">${activeCard}</div></section></div>`;
 return `<div class="ai-brief-section"><h4><span>04</span>人物预选与外貌控制 · 可选</h4><div class="ai-cast-mode-bar"><div class="cast-mode-switch" role="group" aria-label="人物预选控制方式"><button type="button" data-action="ai-cast-mode" data-value="all" class="${b.castMode!=='individual'?'active':''}">全部人物</button><button type="button" data-action="ai-cast-mode" data-value="individual" class="${b.castMode==='individual'?'active':''}">单独控制人物</button></div><small class="help">${b.castMode==='individual'?'单独控制模式：点击上方「人物 1」「人物 2」页签切换编辑不同角色（如一人中国人、一人美国人），互不干扰也无需上下滑动。':'全部人物模式：AI 生成的所有人物默认统一遵循下方国籍面孔（如全部中国人）、颜值档位、肤质磨皮与职业倾向。'}</small></div>${b.castMode==='individual'?indivBox:allBox}</div>`;
}
function aiTabSummaries(b){
 const visName=(AI_VISUALS.find(x=>x[0]===b.visualPreset)?.[1]||'AI自由').split(/[（·]/)[0].trim();
 const span=b.timingMode==='fixed'?`${b.fixedDuration}s/镜`:b.timingMode==='within'?`≤${b.maxMinutes}分`:`${b.duration}s`;
 const dlgName=b.dialogueMode==='silent'?'默片':`${(AI_DIALOGUES.find(x=>x[0]===b.dialogueMode)?.[1]||'自然对白').split('·')[0].trim()}·${b.language||'普通话'}`;
 const castNat=AI_CAST_NATIONALITIES.find(x=>x[0]===b.castDefaults?.nationality)?.[0];
 const bgmName=b.bgmMode==='none'?'无配乐':b.bgmStyle?(GROUPS.bgm.options.find(x=>x.id===b.bgmStyle)?.label?.split(' / ')[0]?.split(' · ')[0]||b.bgmStyle):(b.bgmMode==='guided'||b.bgmMode==='exact'?'已定方向':'AI搭配');
 const storyCount=['genre','tone','characters','setting','conflict','ending','audience','keyLine','avoid','notes'].filter(k=>String(b[k]||'').trim()).length;
 return {
  visual:`${M.aspect(p)}·${p.resolution}·${visName}`,
  timing:b.customShotTiming?`${b.shotCount}镜·${span}`:'AI 自己调整',
  dialogue:dlgName,
  cast:b.castMode==='individual'?`单独${b.castProfiles.length}人`:(castNat||'全部统一'),
  bgm:bgmName,
  story:storyCount?`已填${storyCount}项`:'可选'
 };
}
function aiCreativeControls(){
 const b=ensureAIData(),visual=AI_VISUALS.find(x=>x[0]===b.visualPreset),sum=aiTabSummaries(b);
 const s1=`<div class="ai-brief-section"><h4><span>01</span>先选画面，镜头交给 AI</h4><div class="ai-brief-grid ai-specs-grid">${select('format','画面比例',[['9:16','9:16 · 竖屏短剧'],['16:9','16:9 · 横屏视频'],['2.39:1','2.39:1 · 变形宽银幕电影'],['21:9','21:9 · 超宽电影屏'],['1.85:1','1.85:1 · 院线宽银幕'],['1:1','1:1 · 方形'],['4:3','4:3 · 经典复古横版（港片/胶片感）'],['3:4','3:4 · 经典竖版'],['4:5','4:5 · 社交竖版'],['2:1','2:1 · 现代流媒体比例'],['自定义','自定义比例']])}${select('resolution','画面画质',[['720P','720P · 标准'],['1080P','1080P · 全高清'],['2K','2K · 高清'],['4K','4K · 超高清'],['DCI 4K','DCI 4K · 影院级'],['8K','8K · 极清'],['自定义','自定义像素']])}${select('fps','画面帧率',[[24,'24 fps · 电影感'],[25,'25 fps · 电视制式 / 港剧感'],[30,'30 fps · 流畅短剧'],[12,'12 fps · 港风抽帧 / 动画节奏'],[48,'48 fps · 丝滑动作片'],[50,'50 fps'],[60,'60 fps · 高帧率实拍'],[120,'120 fps · 升格慢动作'],[23.976,'23.976 fps'],[29.97,'29.97 fps'],['自定义','自定义帧率']])}</div>${(p.format==='自定义'||p.resolution==='自定义'||p.fps==='自定义')?`<div class="ai-brief-grid ai-custom-specs">${p.format==='自定义'?input('customFormat','自定义画幅比例',{placeholder:'例如 2.39:1'}):''}${p.resolution==='自定义'?`${input('customWidth','像素宽度',{type:'number',min:1,step:1})}${input('customHeight','像素高度',{type:'number',min:1,step:1})}`:''}${p.fps==='自定义'?input('customFps','自定义帧率',{type:'number',min:.1,step:.001}):''}</div>`:''}<div class="ai-brief-grid">${select('aiBrief.visualPreset','画面风格',AI_VISUALS.map(x=>[x[0],x[1]]))}${select('aiBrief.texturePreset','影像质感',AI_TEXTURES.map(x=>[x[0],x[1]]))}${select('aiBrief.color','画面色调',[['','AI 搭配'],...GROUPS.color.options.map(x=>[x.id,x.label])])}</div><p class="ai-field-note" id="ai-visual-description">${esc(visual?.[2]||'画风可先留给 AI；景别、运镜、对焦和光线会按剧情逐镜设计。')}</p>${aiChoice('visualNotes','补充画风 / 质感',AI_SUGGEST.visualNotes,'可留空，或点右侧箭头挑选现实实拍 / 港风 / 日系胶片等质感')}</div>`;
 const s2=`<div class="ai-brief-section"><h4><span>02</span>镜头数量、节奏与场景转场</h4><div class="ai-shot-mode-switch-wrap">${toggle('aiBrief.customShotTiming','自己设置镜头数量与时长','关闭时由 AI 根据剧情节奏自己调整分镜数与时长；开启此开关后自动展开编辑框。')}</div><div id="ai-auto-shot-note" class="ai-auto-shot-banner" ${b.customShotTiming?'hidden':''}><span class="ai-auto-badge">${icon('spark')} AI 自己调整中</span><small>AI 将按故事起伏、对白容量与画面节奏，自动设计最合理的分镜数量、每镜秒数（≥ 0.5 秒）与全片总时长（已解除 24 镜与 600 秒上限）。</small></div><div id="ai-timing-custom-box" class="ai-timing-custom-box" ${b.customShotTiming?'':'hidden'}><div class="ai-timing-row">${select('aiBrief.shotCountMode','镜头数量方式',[['exact','精确生成 N 镜'],['max','控制在 N 镜内']])}<label class="field ai-count"><span>分镜数量</span><input type="number" aria-label="分镜数量" min="1" step="1" list="ai-shot-counts" data-bind="aiBrief.shotCount" value="${b.shotCount}"><datalist id="ai-shot-counts">${[1,2,3,4,5,6,8,10,12,15,18,20,24,30,36,48,60].map(x=>`<option value="${x}"></option>`).join('')}</datalist></label>${select('aiBrief.timingMode','时长分配',[['auto','AI 按剧情分配'],['fixed','每个镜头固定时长'],['within','控制在 N 分钟内']])}<div id="ai-auto-timing" ${b.timingMode!=='auto'?'hidden':''}>${input('aiBrief.duration','目标总时长 / 秒',{type:'number',min:5,step:1})}</div><div id="ai-fixed-timing" ${b.timingMode!=='fixed'?'hidden':''}>${input('aiBrief.fixedDuration','每镜固定 / 秒',{type:'number',min:.5,step:.5})}</div><div id="ai-within-timing" ${b.timingMode!=='within'?'hidden':''}>${input('aiBrief.maxMinutes','控制在 / 分钟内',{type:'number',min:.1,step:.5})}</div></div><p class="ai-field-note" id="ai-duration-summary" aria-live="polite">${briefTimingSummary(b)}</p><small class="help">分镜数量、单镜秒数与总时长均已解除上限（仅要求分镜 ≥ 1 镜、每镜 ≥ 0.5 秒），可直接输入任意需要数值；注：单次 API 请求仍受 Google Gemini 单回复 65,536 tokens 硬件天花板约束。</small></div><div class="ai-transition-row">${select('aiBrief.transitionStyle','场景A→场景B 与镜头过渡方式',AI_TRANSITION_STYLES)}</div><p class="ai-field-note">支持 6 大类 108 种专业转场（硬切/运镜/特效/叙事/声音/速度）；跨场景可由 AI 自动设计，生成后可在分镜页签间的「⇄ 转场胶囊」微调十项转场规范。</p></div>`;
 const s3=`<div class="ai-brief-section"><h4><span>03</span>让人物开口说话</h4><div class="ai-brief-grid">${select('aiBrief.dialogueMode','对白安排',AI_DIALOGUES)}${aiChoice('language','对白语言',AI_SUGGEST.language)}${aiChoice('dialogueStyle','台词风格',AI_SUGGEST.dialogueStyle)}</div><p class="ai-field-note">默认生成自然对白，连同说话者、声线、语气、微表演和音效填入分镜与「表演与声音」。无对白请主动选择默片。</p></div>`;
 const s4=aiCastControls(b);
 const s5=`<div class="ai-brief-section"><h4><span>05</span>背景音乐与配乐（BGM）</h4><div class="ai-brief-grid">${select('aiBrief.bgmMode','配乐方式',AI_BGM_MODES)}${select('aiBrief.bgmStyle','配乐风格方向',[['','AI 按剧情自动选曲 / 不固定'],...GROUPS.bgm.options.filter(x=>x.id!=='none').map(x=>[x.id,x.label]),['none','无背景音乐（仅保留环境声与对白）']])}${dataliChoice('aiBrief.bgmMood','ai-bgm-moods','情绪走势与节奏',AI_BGM_MOOD_EXAMPLES,'例如：前期克制留白，高潮弦乐推高')}</div>${input('aiBrief.bgmNotes','配乐细节补充（乐器 / 进出时机 / 避让台词）',{placeholder:'例如：前5秒静默留雨声；第6秒钢琴轻入；人物说话时配乐自动压低（可留空或点右侧箭头选预设）'})}<p class="ai-field-note" id="ai-bgm-note">${esc(aiBgmHintText(b))}</p></div>`;
 const s6=`<div class="ai-brief-section"><h4><span>06</span>剧情方向 · 关系、冲突、结局与必说台词</h4><div class="ai-brief-grid two">${aiChoice('genre','故事类型',AI_SUGGEST.genre)}${aiChoice('tone','情绪与节奏',AI_SUGGEST.tone)}${aiChoice('characters','人物与关系',AI_SUGGEST.characters)}${aiChoice('setting','地点与时间',AI_SUGGEST.setting)}${aiChoice('conflict','主要矛盾',AI_SUGGEST.conflict)}${aiChoice('ending','结局方式',AI_SUGGEST.ending)}${aiChoice('audience','目标观众 / 平台',AI_SUGGEST.audience)}${aiChoice('keyLine','必须出现的台词',AI_SUGGEST.keyLine,'可留空，或填写需要原样保留的一句话')}${aiChoice('avoid','避免的内容',AI_SUGGEST.avoid)}</div>${input('aiBrief.notes','其他创作要求',{area:true,placeholder:'例如：第一镜就交代冲突，最后一个镜头留下悬念（可点下方「参考示例」一键参考）'})}</div>`;
 const tabs=[['visual','01','画面与比例',sum.visual],['timing','02','镜头与转场',sum.timing],['dialogue','03','对白配音',sum.dialogue],['cast','04','人物预选',sum.cast],['bgm','05','背景配乐',sum.bgm],['story','06','剧情细化',sum.story]];
 const panels={visual:s1,timing:s2,dialogue:s3,cast:s4,bgm:s5,story:s6};
 return `<section class="web-tabs-shell ai-web-tabs">${webTabBar('ai-tab',aiTab,tabs)}<div class="web-tab-panel">${panels[aiTab]||s1}</div></section>`;
}

function aiWaitText(){const sec=aiFlow.startedAt?Math.max(0,Math.floor((Date.now()-aiFlow.startedAt)/1000)):0,m=String(Math.floor(sec/60)).padStart(2,'0'),s=String(sec%60).padStart(2,'0');return `正在生成画面、逐秒时间轴、微表演、对白与声音（已等待 ${m}:${s}；高思考档位+多镜通常需 1–3.5 分钟，超时上限 15 分钟）。已有内容保留；离开或编辑页面后，方案会先保留为建议。`;}
function aiSuggestion(){return p.aiSuggestion||aiResults.get(p.id)||null;}
function connectionPill(kind){const entry=kind==='ai'?activeAIService():creationServices[kind],ready=!!entry?.ready;return `<span class="connection-pill ${ready?'configured':'pending'}" data-service="${kind}">${creationServices.loading&&!personalAI.key?'读取状态…':ready?entry.personal?(entry.verified?'个人已验证':'个人已配置'):'站点已配置':'待连接'}</span>`;}
function aiStudioView(){const brief=ensureAIData(),suggestion=aiSuggestion();return heading('AI DIRECTOR / 想法成稿','先定你想要的，再让 AI 开拍。','先选风格、节奏、首尾衔接、切点防跳检查与转场偏好，再自动生成包含逐秒时间轴与十项转场规范的可编辑分镜。',btn('navigate','服务连接','settings','btn subtle','data-view="connections"'))+`<div class="studio-service-line"><span>${icon('spark')}<strong>${esc(activeAIService().name||'Gemini 4 Hydrogen')}</strong>${connectionPill('ai')}</span><small data-service-reason="ai">${esc(activeAIService().reason)}</small></div>`+panel('你想拍什么？',input('aiBrief.idea','创作想法',{area:true,placeholder:'写下一句话故事。画风、镜头节奏、连贯控制与对白可以在下面选择，不必一次写完整。'})+`<div class="ai-continuity-strip" id="ai-continuity-strip"><div class="continuity-pill-row"><label class="chain-inline-toggle ${brief.chainLastFrame?'active':''}"><input type="checkbox" data-bind="aiBrief.chainLastFrame" ${brief.chainLastFrame?'checked':''}><span>尾帧接下一镜首帧</span></label><label class="chain-inline-toggle cut-check-pill ${brief.cutFrameCheck?'active':''}"><input type="checkbox" data-bind="aiBrief.cutFrameCheck" ${brief.cutFrameCheck?'checked':''}><span>切点前后两帧检查</span></label><span class="ai-tip-wrap" tabindex="0" aria-describedby="ai-continuity-note"><span class="ai-tip-trigger">${icon('info')}<span>提示</span></span><span class="ai-tip-popover" role="tooltip"><small class="help ai-continuity-note" id="ai-continuity-note">${esc(aiContinuityHintText(brief))}</small></span></span></div></div>`+aiCreativeControls()+`<div class="ai-behavior-options">`+toggle('aiBrief.reuse','参考当前人物与场景','复用文字设定与锁定造型；画风优先使用上方选择。')+toggle('aiBrief.autoFill','生成后自动填入工作台','已有内容时另存新项目；关闭后先预览方案。')+`</div><div class="ai-request-actions">${btn('ai-generate',aiFlow.busy?'正在等待方案…':suggestion?'按新设定重新生成':'生成填写方案','spark','btn primary',`data-requires-ai ${!activeAIService().ready||aiFlow.busy?'disabled':''}`)}${aiFlow.busy?btn('ai-cancel','取消等待','','btn subtle'):btn('ai-example','查看内置示例','','btn subtle')}${p.logline?btn('ai-use-logline','带入当前想法','','text-btn'):''}</div><p class="help ai-request-note" id="ai-request-note">${aiFlow.busy?aiWaitText():'正式生成使用所选 API 额度；内置示例不调用 AI。'}</p>${aiFlow.error?hint(esc(aiFlow.error),'warning'):''}`)+(suggestion?aiSuggestionPanel(suggestion):`<div class="ai-waiting"><span>${icon('board')}</span><h3>画风、对白和节奏，都按你的方向。</h3><p>先写故事，细节可以从参考选项中挑选。<br>AI 负责设计运镜、逐秒动作、场景转场与声音时间轴，你保留最后的修改权。</p>${!activeAIService().ready?btn('navigate','连接我的API','arrow','text-btn','data-view="connections"'):''}</div>`);}

function aiSuggestionPanel(suggestion){const plan=suggestion.plan,applied=suggestion.applied,bgmLabel=plan.bgm?.style?`${M.label(p,'bgm',plan.bgm.style)}${plan.bgm.mood?' · '+plan.bgm.mood:''}`:'';return panel('填写方案预览',`<div class="ai-result-meta"><span class="origin-tag ${suggestion.origin==='demo'?'example':''}">${suggestion.origin==='demo'?'内置示例 · 非AI生成':'AI建议 · '+esc(suggestion.model)}</span>${plan.chainLastFrame?'<span class="ai-chain-badge">尾帧承接首帧已开启</span>':''}${plan.cutFrameCheck?'<span class="ai-chain-badge">切点两帧检查已开启</span>':''}${plan.bgm?.style?`<span class="ai-chain-badge">BGM · ${esc(M.label(p,'bgm',plan.bgm.style))}</span>`:''}<span data-ai-meta="summary">${plan.characters.length} 人物 · ${plan.scenes.length} 场景 · ${plan.shots.length} 镜头 · ${M.fmt(plan.shots.reduce((n,s)=>n+s.duration,0))}秒</span></div><label class="field"><span>项目名称</span><input aria-label="方案项目名称" data-ai-edit="title" value="${esc(plan.title)}" ${applied?'disabled':''}></label><label class="field"><span>一句话剧情</span><textarea rows="2" aria-label="方案剧情" data-ai-edit="logline" ${applied?'disabled':''}>${esc(plan.logline)}</textarea></label><div class="ai-asset-summary"><span>${icon('person')}${esc(plan.characters.map(c=>c.name).join('、')||'未建议人物')}</span><span>${icon('scene')}${esc(plan.scenes.map(s=>s.name).join('、')||'未建议场景')}</span><span>${icon('sound')}${esc(bgmLabel||'配乐随分镜声音时间轴安排')}</span></div><div class="ai-preview-shots">${plan.shots.map((s,i)=>`<details class="ai-preview-shot" data-ai-shot="${i}" ${i===0?'open':''}><summary><span>${String(i+1).padStart(2,'0')}</span><strong data-ai-shot-title>${esc(s.title)}</strong><small data-ai-shot-duration>${s.duration}秒${s.segments?.length?` · ${s.segments.length}段时序`:''}</small>${icon('chevron')}</summary><div><div class="grid two"><label class="field"><span>镜头名称</span><input aria-label="方案镜头${i+1}名称" data-ai-edit="shots.${i}.title" value="${esc(s.title)}" ${applied?'disabled':''}></label><label class="field numeric-field"><span>时长 / 秒</span><input type="number" min="0.5" step="0.5" aria-label="方案镜头${i+1}时长" data-ai-edit="shots.${i}.duration" value="${s.duration}" ${applied?'disabled':''}></label></div><label class="field"><span>发生什么</span><textarea rows="2" aria-label="方案镜头${i+1}动作" data-ai-edit="shots.${i}.action" ${applied?'disabled':''}>${esc(s.action)}</textarea></label>${s.dialogue?`<label class="field"><span>对白 · ${esc(plan.characters.find(c=>c.ref===s.speakerRef)?.name||'说话人物')}</span><textarea rows="2" aria-label="方案镜头${i+1}对白" data-ai-edit="shots.${i}.dialogue" ${applied?'disabled':''}>${esc(s.dialogue)}</textarea><small>${esc(s.delivery||'自然语气')} · ${esc(s.dialogueLanguage||'普通话')} · ${s.dialogueStart}–${s.dialogueEnd}s</small></label>`:''}${s.endState?`<small class="muted">收尾：${esc(s.endState)}</small>`:''}${(s.intent||s.spatial||s.segments?.length||s.soundCues?.length||s.transition)?`<div class="ai-shot-extra">${s.intent?`<span><b>导演意图：</b>${esc(s.intent)}</span>`:''}${s.spatial?`<span><b>空间视线：</b>${esc(s.spatial)}</span>`:''}${s.segments?.length?`<span><b>镜内时间轴（${s.segments.length}段）：</b>${s.segments.map(x=>`${x.start}–${x.end}s ${esc(x.action)}`).join('；')}</span>`:''}${s.soundCues?.length?`<span><b>声音时间轴（${s.soundCues.length}条）：</b>${s.soundCues.map(q=>`${q.start}s ${esc(q.cue)}`).join('；')}</span>`:''}${s.transition?`<span><b>场景/镜头转场：</b>${esc(M.label(p,'transition',s.transition))}${s.transitionSpec?.process?' · '+esc(s.transitionSpec.process):''}</span>`:''}</div>`:''}</div></details>`).join('')}</div>${p.mode==='commerce'?`<div class="ai-commerce-summary"><strong>商品建议</strong><p>${esc([plan.commerce.name,plan.commerce.sellingPoints,plan.commerce.scene].filter(Boolean).join(' · ')||'未提供新的商品信息，已有信息保留。')}</p></div>`:''}<div class="ai-scope-list"><span>应用哪些内容</span>${Object.entries({story:'项目与剧情',style:'质感与限制',characters:'人物设定',scenes:'场景光线',shots:'分镜',commerce:'商品信息'}).filter(([k])=>k!=='commerce'||p.mode==='commerce').map(([k,l])=>`<label><input type="checkbox" data-ai-scope="${k}" ${aiScopes[k]?'checked':''} ${applied?'disabled':''}>${l}</label>`).join('')}</div><label class="field"><span>应用方式</span><select aria-label="AI方案应用方式" data-ui="ai-apply-mode" ${applied?'disabled':''}><option value="fill" ${aiApplyMode==='fill'?'selected':''}>补充当前项目 · 已有内容和锁定项保留</option><option value="new" ${aiApplyMode==='new'?'selected':''}>另存为新项目 · 保留当前项目</option></select></label><p class="help">勾选分镜时会新增镜头；现有镜头保留。缺少同名资产时，需要同时应用对应人物和场景。应用后仍可修改，也可撤销。</p><div class="ai-apply-actions">${btn('ai-apply',applied?'方案已应用':suggestion.origin==='demo'?'应用示例方案':'应用填写方案','check','btn primary',applied||aiFlow.busy?'disabled':'')}${applied?btn('navigate',p.mode==='commerce'?'继续编辑商品':'继续编辑分镜','arrow','btn subtle',`data-view="${p.mode==='commerce'?'commerce':'storyboard'}"`):''}</div>`,'建议先检查故事和动作，再决定应用。');}
async function loadCreationServices(){creationServices.loading=true;renderCreationStatus();try{const r=await fetch('/api/config',{credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(12000)});const data=await readCreationResponse(r);creationServices={loading:false,ai:data.ai,video:data.video};}catch(e){creationServices={loading:false,ai:{ready:false,name:'Gemini 4 Hydrogen',reason:e.message||'连接状态读取失败，请重试'},video:{ready:false,reason:'视频服务状态尚未确认'}};}renderCreationStatus();}
function renderCreationStatus(){for(const badge of $$('[data-service]')){const s=badge.dataset.service==='ai'?activeAIService():creationServices[badge.dataset.service],ready=!!s?.ready;badge.textContent=creationServices.loading&&!personalAI.key?'读取状态…':ready?s.personal?(s.verified?'个人已验证':'个人已配置'):'站点已配置':'待连接';badge.className='connection-pill '+(ready?'configured':'pending');}for(const el of $$('[data-service-reason]'))el.textContent=(el.dataset.serviceReason==='ai'?activeAIService():creationServices[el.dataset.serviceReason])?.reason||'服务尚未配置';for(const b of $$('[data-requires-ai]'))b.disabled=!activeAIService().ready||aiFlow.busy;}
async function requestAIFill(){if(aiFlow.busy)return;if(!activeAIService().ready){toast('请先连接自己的 Google API Key。');navigateToView('connections');return;}const brief=ensureAIData();let payload;try{payload=normalizePlanRequest({idea:brief.idea,shotControlMode:brief.customShotTiming?'custom':'auto',duration:brief.duration,shotCount:Number(brief.shotCount),shotCountMode:brief.shotCountMode,timingMode:brief.timingMode,fixedDuration:brief.fixedDuration,maxMinutes:brief.maxMinutes,preferences:brief,mode:p.mode==='commerce'?'commerce':'story',context:brief.reuse?contextForAI(p):{}});}catch(e){toast(e.message,'error');return;}if(personalAI.key)payload.connection={provider:'google',model:personalAI.model};const sourceId=p.id,startRevision=revision,autoFill=!!brief.autoFill,requestId=M.uid(),controller=new AbortController();clearInterval(aiFlow.timer);const timer=setInterval(()=>{const n=$('#ai-request-note');if(n&&aiFlow.busy)n.textContent=aiWaitText();},1000);aiFlow={busy:true,error:'',requestId,controller,startedAt:Date.now(),timer};renderMain();try{let data;if(personalAI.key&&personalAI.transport!=='server')data=await generateGooglePlan(payload,{GEMINI_API_KEY:personalAI.key,GEMINI_MODEL:personalAI.model},{signal:controller.signal});else{const response=await fetch('/api/ai/plan',{method:'POST',credentials:'same-origin',headers:personalAIHeaders(),body:JSON.stringify(payload),signal:controller.signal});data=await readCreationResponse(response);}if(aiFlow.requestId!==requestId)return;const result={plan:normalizePlan(data.plan),origin:'ai',sourceReuse:!!brief.reuse,model:data.model,generatedAt:data.generatedAt,projectId:sourceId,applied:false};aiResults.set(sourceId,result);if(p.id===sourceId){const untouched=canAutoFill({enabled:autoFill,sourceId,currentId:p.id,startRevision,currentRevision:revision,view,surface}),existing=hasAuthoredAIProject(p);remember();p.aiSuggestion=result;changed();if(autoFill&&untouched)await applySuggestion({automatic:true,asNewOverride:existing,scopesOverride:DEFAULT_AI_SCOPES});else toast(autoFill?'方案已返回；你已开始其他编辑，先保留为建议，确认后再填入。':'方案已返回，检查后可选择应用。');}else toast('原项目的方案已返回，可回到原项目的AI填写页查看。');}catch(e){if(aiFlow.requestId===requestId)aiFlow.error=e.name==='AbortError'?'已取消等待，本次内容没有应用。':e.message||'暂时无法获得填写方案';}finally{if(aiFlow.requestId===requestId){clearInterval(aiFlow.timer);aiFlow.busy=false;aiFlow.controller=null;aiFlow.startedAt=0;aiFlow.timer=null;if(surface==='studio'&&view==='ai')renderMain();else if(aiFlow.error)toast(aiFlow.error,'error');renderCreationStatus();}}}
function loadExampleProposal(){remember();const result={plan:exampleAIPlan(),origin:'demo',model:'内置流程示例',generatedAt:null,projectId:p.id,applied:false};p.aiSuggestion=result;aiResults.set(p.id,result);aiFlow.error='';changed({refresh:true});toast('这是内置示例，不是AI生成；原有设定还未应用。');}
async function applySuggestion({automatic=false,asNewOverride,scopesOverride}={}){const suggestion=aiSuggestion();if(!suggestion||suggestion.applied||aiFlow.busy&&!automatic)return;if(suggestion.projectId!==p.id)throw Error('方案来自其他项目，请回到原项目后再应用。');const chosenScopes=scopesOverride||aiScopes,asNew=asNewOverride??aiApplyMode==='new';if(!Object.values(chosenScopes).some(Boolean))throw Error('请至少选择一部分需要应用的内容。');const result=applyAIPlan(p,suggestion.plan,{scopes:chosenScopes,asNew,origin:suggestion.origin,reuseExistingAssets:suggestion.sourceReuse!==false});const previousShotCount=asNew?0:p.shots.length;result.project.aiSuggestion={...M.clone(suggestion),projectId:result.project.id,applied:true};if(asNew)await changeProject(result.project);else{remember();p=result.project;changed({refresh:true});}selected=Math.min(previousShotCount,Math.max(0,p.shots.length-1));if(p.shots[selected])expandedShots.add(p.shots[selected].id);view=p.mode==='commerce'?'commerce':p.shots.length?'storyboard':'characters';render();$('#main').scrollTop=0;if(await persist())toast(`方案已应用，新增${result.report.shotsAdded}个镜头，已有填写和锁定项保留。`);}
function initVideoDraft(){const fresh=!p.videoDraft;const d=ensureVideoData(p);if(fresh){d.prompt=M.generate(p,selected);d.duration=Math.min(120,M.totalDuration(p)||20);}return d;}
function videoStudioView(){const draft=initVideoDraft(),results=p.videoResults||[],jobs=p.videoJobs||[];return heading('VIDEO STUDIO / 视频创作','把下一段视频，准备好。','从提示词、参考图到生成计划；服务接入后，视频也会回到这里。',btn('navigate','服务连接','settings','btn subtle','data-view="connections"'))+`<div class="studio-service-line"><span>${icon('camera')}<strong>视频生成服务</strong>${connectionPill('video')}</span><small data-service-reason="video">${esc(creationServices.video.reason)}</small></div><div class="video-studio-tabs">${[['compose','生成设置'],['tasks',`生成计划 ${jobs.length}`],['results',`视频预览 ${results.length}`]].map(([k,l])=>btn('video-tab',l,'',`tag-button ${videoStudioTab===k?'selected':''}`,`data-value="${k}"`)).join('')}</div>`+(videoStudioTab==='compose'?videoCompose(draft):videoStudioTab==='tasks'?videoTaskList(jobs):videoResultView(results));}
function videoCompose(draft){const images=p.references.filter(r=>r.type==='image');return panel('生成前，先确认画面',select('videoDraft.source','提示词来源',[['project','当前项目输出'],...p.shots.map((s,i)=>['shot:'+s.id,`镜头${i+1} · ${s.title}`]),['custom','手动填写']])+input('videoDraft.prompt','视频提示词',{area:true,placeholder:'从右侧输出带入，或在这里填写需要生成的视频内容。'})+`<div class="video-prompt-actions">${btn('video-refresh-prompt','重新带入提示词','undo','text-btn')}${btn('video-copy-draft','复制生成提示词','copy','text-btn')}</div><div class="grid two">${select('videoDraft.mode','生成方式',[['text','文生视频'],['reference','参考图视频'],['frames','首尾帧视频']])}${input('videoDraft.duration','目标时长 / 秒',{type:'number',min:1,step:1})}${select('videoDraft.format','目标画幅',['9:16','16:9','1:1','4:3','2.39:1'])}${select('videoDraft.resolution','目标画质',['720P','1080P','2K','4K','8K'])}</div><p class="help video-timing-hint" id="video-timing-hint">${esc(videoTimingText())}</p>${draft.mode==='reference'?`<div class="video-reference-list"><span>选择参考图片</span>${images.map(r=>`<label><input type="checkbox" data-video-ref="${r.id}" ${(draft.referenceIds||[]).includes(r.id)?'checked':''}>${esc(r.name)}<small>${r.data?'已上传':'待上传'}</small></label>`).join('')||btn('navigate','去添加参考图片','plus','btn subtle','data-view="references"')}</div>`:draft.mode==='frames'?`<div class="grid two">${select('videoDraft.firstFrameId','首帧图片',[['','请选择首帧'],...images.map(r=>[r.id,r.name])])}${select('videoDraft.lastFrameId','尾帧图片',[['','请选择尾帧'],...images.map(r=>[r.id,r.name])])}</div>${!images.length?btn('navigate','去添加首尾帧图片','plus','text-btn','data-view="references"'):''}`:''}${input('videoDraft.notes','生成备注',{area:true,placeholder:'例如：只参考人物外貌，不使用参考图背景。'})}<p class="help">时长、画幅和画质是创作目标；接入服务后还需按模型支持范围校验。这里修改的提示词不会覆盖原分镜。</p><div class="video-compose-actions">${btn('video-save-plan','保存生成计划','check','btn primary')}${btn('video-submit','提交生成 · 待接入','camera','btn subtle','disabled title="视频API尚未连接，不会提交或扣费"')}</div><p class="help">当前可以保存计划。尚未连接 Muse API，不会自动使用账号额度。</p>`)+`<section class="video-preview-placeholder">${icon('camera')}<h3>视频结果，会在这里相遇。</h3><p>完成接入后用于展示生成结果。<br>现在也可以添加已有视频链接，使用预览窗口。</p>${btn('video-import-result','添加已有视频链接','plus','btn subtle small')}</section>`;}
function videoTaskList(jobs){return jobs.length?`<div class="video-job-list">${jobs.slice().reverse().map(j=>`<article class="video-job"><div><span class="video-job-icon">${icon('film')}</span><span><strong>${esc(j.name)}</strong><small>${j.duration}秒 · ${esc(j.format)} · ${esc(j.resolution)}</small></span><em>待提交计划</em></div><p>${esc(j.prompt.slice(0,200))}${j.prompt.length>200?'…':''}</p><small>保存在当前项目 · 尚未提交到服务商</small><footer>${btn('video-copy-plan','复制提示词','copy','text-btn',`data-id="${j.id}"`)}${btn('video-reuse-plan','继续编辑','settings','text-btn',`data-id="${j.id}"`)}${btn('video-delete-plan','移除计划','trash','text-btn danger',`data-id="${j.id}"`)}</footer></article>`).join('')}</div>`:`<div class="ai-waiting">${icon('board')}<h3>先准备好第一条生成计划</h3><p>保存提示词和参考设置，接口接好后再提交。</p>${btn('video-tab','前往生成设置','arrow','btn primary small','data-value="compose"')}</div>`;}
function videoResultView(results){const active=results.find(x=>x.id===videoSelectedResultId)||results.at(-1),url=active&&safeVideoURL(active.url);return `<div class="video-results-toolbar"><p>已有视频与未来生成结果的预览窗口。</p>${btn('video-import-result','添加视频链接','plus','btn primary small')}</div>${active&&url?`<section class="video-player-wrap"><div><strong>${esc(active.title)}</strong><span>手动导入</span></div><video controls preload="none" playsinline src="${esc(url)}" aria-label="${esc(active.title)}视频预览"></video><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">打开原视频 ${icon('arrow')}</a></section><div class="video-result-list">${results.map(r=>`<div><button data-action="video-select-result" data-id="${r.id}" class="${r.id===active.id?'active':''}">${icon('film')}${esc(r.title)}<small>已导入</small></button>${btn('video-delete-result','','trash','icon-btn danger',`data-id="${r.id}" aria-label="移除${esc(r.title)}链接"`)}</div>`).join('')}</div><p class="help">这里只保存视频链接。重要视频请另行下载留存；移除链接不会删除服务商的视频文件。</p>`:`<section class="video-preview-placeholder tall">${icon('camera')}<h3>还没有视频结果</h3><p>添加已有视频链接后，可以在这里播放。<br>视频API暂未连接，没有生成中的任务。</p></section>`}`;}

function refreshVideoPrompt(recordHistory=true){const d=initVideoDraft();if(d.source==='custom'){toast('当前为手动填写模式，已有文字保留。');return;}let prompt;if(d.source==='project')prompt=M.generate(p,selected);else{const index=p.shots.findIndex(s=>'shot:'+s.id===d.source);if(index<0){toast('原镜头已移除，请重新选择来源。');return;}prompt=M.generate(p,index,'shot');}if(recordHistory)remember();d.prompt=prompt;changed({refresh:true});}
function importVideoModal(){modal('添加已有视频链接',hint('用于预览已有作品；不会调用生成API。视频链接保存在当前项目，播放时由浏览器直接读取。')+`<label class="field"><span>视频名称</span><input id="video-result-title" maxlength="100" placeholder="例如：雨夜重逢·第一版"></label><label class="field"><span>HTTPS视频链接</span><input id="video-result-url" type="url" placeholder="https://…/video.mp4"></label>`,btn('close-modal','取消','','btn subtle')+btn('video-confirm-import','添加到预览','plus','btn primary'));}

function videoOutputPanel(){const d=initVideoDraft(),text=videoPromptText(d,M.frameRate(p));return `<div class="preview-heading"><div><span class="eyebrow">VIDEO PROMPT</span><h2>本次生成计划</h2></div>${btn('close-preview','','close','icon-btn mobile-only','aria-label="关闭预览"')}</div><div class="video-output-specs"><span>${esc(d.format)}</span><span>${esc(d.resolution)}</span><span>${d.duration}秒 · 目标</span></div><div class="studio-service-line">${connectionPill('video')}<small>接口未连接 · 不会自动提交</small></div><div class="prompt-scroll"><div class="prompt-paper video-output-paper" id="prompt-text" tabindex="0">${text?esc(text):'<div class="empty-prompt">先准备这一段视频的提示词<br><small>可以带入原有输出，也可以单独修改。</small></div>'}</div></div><p class="output-footnote">这里只影响视频生成计划，不会改写原分镜。实际可生成规格取决于接入服务。</p><div class="copy-area">${btn('video-copy-draft','复制生成提示词','copy','btn primary copy-primary',text?'':'disabled')}</div>`;}
function videoTimingText(){const d=p.videoDraft;if(!d||d.source==='custom')return '';const shot=d.source.startsWith('shot:')?p.shots.find(s=>'shot:'+s.id===d.source):null,seconds=shot?Number(shot.duration):M.totalDuration(p);return seconds&&Number(d.duration)!==seconds?`原分镜约${M.fmt(seconds)}秒，本次生成目标为${d.duration}秒；如需一致，可回到分镜调整节奏。`:'';}

function activeAIService(){if(personalAI.key)return {ready:true,provider:'google',model:personalAI.model,name:personalAI.model==='gemini-4-hydrogen'?'Gemini 4 Hydrogen':personalAI.model,reason:(personalAI.transport==='server'?'服务器转发':'浏览器直连')+(personalAI.verified?' · 已通过连接检查':' · 尚未验证'),personal:true,verified:personalAI.verified};return creationServices.ai;}
function personalAIHeaders(){return {'Content-Type':'application/json',...(personalAI.key?{'x-jingxu-api-key':personalAI.key}:{})};}
function readPersonalConnection(){const raw=$('#personal-ai-key')?.value||personalAI.key||'',model=normalizeGoogleModel($('#personal-ai-model')?.value||personalAI.model);return {key:normalizeGoogleKey(raw),model,transport:($('#personal-ai-transport')?.value||personalAI.transport)==='server'?'server':'browser',verified:false};}
function updatePersonalFeedback(){const el=$('#personal-connection-feedback');if(el){el.textContent=personalConnection.message;el.hidden=!personalConnection.message;el.className='personal-connection-feedback '+(personalConnection.error?'error':'');}for(const b of $$('[data-action="use-personal-ai"],[data-action="test-personal-ai"],[data-action="disconnect-personal-ai"]'))b.disabled=personalConnection.busy;for(const field of $$('#personal-ai-key,#personal-ai-model,#personal-ai-transport'))field.disabled=personalConnection.busy;}
async function testPersonalConnection({openEditor=false}={}){if(personalConnection.busy)return;let candidate;try{candidate=readPersonalConnection();}catch(e){personalConnection={busy:false,message:e.message,error:true};updatePersonalFeedback();return;}personalConnection={busy:true,message:'正在向 Google 验证密钥和模型访问权限，不会生成内容…',error:false};updatePersonalFeedback();try{let data;if(candidate.transport==='browser')data=await testGoogleConnection({GEMINI_API_KEY:candidate.key,GEMINI_MODEL:candidate.model});else{const response=await fetch('/api/ai/connection',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','x-jingxu-api-key':candidate.key},body:JSON.stringify({connection:{provider:'google',model:candidate.model}}),signal:AbortSignal.timeout(25000)});data=await readCreationResponse(response);}if(data.verified!==true)throw Error('没有获得 Google 的模型访问确认，本次连接未启用。');personalAI={...candidate,verified:true};prefs.personalAI={provider:'google',model:candidate.model,transport:candidate.transport};persistPrefs();personalConnection={busy:false,message:'Google 已确认模型访问权限，可以开始 AI 填写。',error:false};if(surface==='studio'&&view==='connections'){if(openEditor){view='ai';render();}else renderMain();}renderCreationStatus();toast('连接已验证。输入想法后点击生成，即可自动填入。');}catch(e){personalConnection={busy:false,message:e.name==='TimeoutError'||e.name==='AbortError'?'连接检查超时，请稍后再试；本次没有生成内容。':e.message||'无法连接 Google，请稍后重试。',error:true};updatePersonalFeedback();}finally{personalConnection.busy=false;updatePersonalFeedback();}}
function connectionView(){const service=activeAIService();return heading('MY API / 个人模型连接','接上你的 API，开始自动创作。','使用自己的 Google API Key。AI 填入人物、场景与分镜，你继续修改。',btn('refresh-services','刷新站点状态','undo','btn subtle'))+`<section class="connection-card personal-api-card"><div><span class="connection-icon">${icon('spark')}</span><span><small>我的 AI 接口 · Google 官方</small><h2>${esc(service.name||'Gemini 4 Hydrogen')}</h2></span>${connectionPill('ai')}</div><p>默认模型 Hydrogen。浏览器直连与参考聊天页采用相同路径，也可选择服务器转发。密钥只在当前页面内存中使用，不写入项目或长期存储。</p><div class="grid two"><label class="field"><span>服务商</span><select aria-label="AI服务商" disabled><option>Google Gemini API</option></select></label><label class="field"><span>模型 ID</span><input id="personal-ai-model" aria-label="个人模型ID" value="${esc(personalAI.model)}" autocomplete="off" spellcheck="false" placeholder="gemini-4-hydrogen"></label></div><label class="field"><span>连接方式</span><select id="personal-ai-transport" aria-label="Google连接方式"><option value="browser" ${personalAI.transport!=='server'?'selected':''}>浏览器直连 · 参考聊天页方式</option><option value="server" ${personalAI.transport==='server'?'selected':''}>服务器转发</option></select></label><label class="field personal-key-field"><span>Google API Key</span><input id="personal-ai-key" aria-label="个人Google API Key" type="password" autocomplete="off" spellcheck="false" maxlength="8192" placeholder="${personalAI.key?'本次已连接；留空可继续使用当前Key':'粘贴你的 Google API Key'}"></label><div class="personal-api-actions">${btn('use-personal-ai','连接并开始填写','arrow','btn primary small',personalConnection.busy?'disabled':'')}${btn('test-personal-ai','测试连接','settings','btn subtle small')}${personalAI.key?btn('disconnect-personal-ai','断开个人连接','','text-btn danger'):''}</div><p class="help personal-key-note">支持 Google 的标准密钥与授权密钥。连接时只检查模型访问，不生成内容。刷新页面后需重新连接；正式生成使用你的 Google 项目额度。</p><div id="personal-connection-feedback" role="status" aria-live="polite" class="personal-connection-feedback ${personalConnection.error?'error':''}" ${personalConnection.message?'':'hidden'}>${esc(personalConnection.message)}</div><div class="personal-connection-status"><span data-service-reason="ai">${esc(service.reason)}</span></div><footer>${btn('open-ai','输入想法，让AI填写','arrow','btn primary small')}<a href="https://aistudio.google.com/docs/api-key" target="_blank" rel="noopener noreferrer">Google API Key说明 ${icon('arrow')}</a></footer></section><section class="connection-card video-pending"><div><span class="connection-icon">${icon('camera')}</span><span><small>我的视频接口 · 预留</small><h2>Muse / 视频生成服务</h2></span>${connectionPill('video')}</div><p data-service-reason="video">${esc(creationServices.video.reason)}</p><ul><li>已预留提示词、参考图、首尾帧、生成计划与结果预览</li><li>确认 Muse 平台的 API 文档后，再接入个人视频密钥</li><li>网页账号额度是否支持API，需由对应服务商确认</li></ul><footer>${btn('navigate','打开视频创作','arrow','btn subtle small','data-view="video"')}${btn('integration-guide','接入说明','book','text-btn')}</footer></section><details class="progressive-details"><summary>站点公共服务 · 可选</summary><div class="disclosure-body"><p class="help">未连接个人API时，可使用站点已启用的公共服务。当前状态：${creationServices.ai.ready?'已配置':'未配置'}。个人连接优先，密钥不会保存到站点环境变量。</p></div></details>`;}

function updateAIBriefControls(){if(view!=='ai')return;const b=ensureAIData(),visual=AI_VISUALS.find(x=>x[0]===b.visualPreset);if($('#ai-auto-shot-note'))$('#ai-auto-shot-note').hidden=!!b.customShotTiming;if($('#ai-timing-custom-box'))$('#ai-timing-custom-box').hidden=!b.customShotTiming;if($('#ai-auto-timing'))$('#ai-auto-timing').hidden=b.timingMode!=='auto';if($('#ai-within-timing'))$('#ai-within-timing').hidden=b.timingMode!=='within';if($('#ai-fixed-timing'))$('#ai-fixed-timing').hidden=b.timingMode!=='fixed';if($('#ai-duration-summary')){const summary=briefTimingSummary(b);$('#ai-duration-summary').textContent=summary;$('#ai-duration-summary').classList.toggle('is-warning',summary.includes('请填写')||summary.includes('提示：'));}if($('#ai-visual-description'))$('#ai-visual-description').textContent=visual?.[2]||'画风可先留给 AI；景别、运镜、对焦和光线会按剧情逐镜设计。';if($('#ai-continuity-note'))$('#ai-continuity-note').textContent=aiContinuityHintText(b);if($('#ai-bgm-note'))$('#ai-bgm-note').textContent=aiBgmHintText(b);const cPill=$('input[data-bind="aiBrief.chainLastFrame"]')?.closest('.chain-inline-toggle');if(cPill)cPill.classList.toggle('active',!!b.chainLastFrame);const kPill=$('input[data-bind="aiBrief.cutFrameCheck"]')?.closest('.chain-inline-toggle');if(kPill)kPill.classList.toggle('active',!!b.cutFrameCheck);for(const [k,txt] of Object.entries(aiTabSummaries(b))){const el=$(`[data-tab-meta="ai-tab:${k}"]`);if(el)el.textContent=txt;}if(b.castMode==='individual'){const prof=b.castProfiles[aiCastTab];if(prof){const meta=$(`[data-tab-meta="ai-cast-tab:${aiCastTab}"]`),titleEl=meta?.previousElementSibling,head=$('.cast-profile-head strong');if(titleEl)titleEl.textContent=prof.name||`人物 ${aiCastTab+1}`;if(meta)meta.textContent=AI_CAST_NATIONALITIES.find(x=>x[0]===prof.nationality)?.[0]||prof.nationality||'待选';if(head)head.textContent=`正在编辑 · 人物 ${aiCastTab+1}${prof.name?' · '+prof.name:''}`;}}}

function performanceDialogueIndex(){const spoken=p.shots.filter(s=>s.dialogue);return `<details class="progressive-details dialogue-index"><summary>全片对白 · ${spoken.length} / ${p.shots.length} 镜有台词 <span>点击定位编辑</span></summary><div class="disclosure-body">${p.shots.map((s,i)=>`<button type="button" data-action="edit-speech" data-index="${i}" class="dialogue-index-row ${i===selected?'selected':''}"><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(p.characters.find(c=>c.id===s.speakerId)?.name||s.title)}</strong><span>${esc(s.dialogue||'本镜无对白，点击补充')}</span><small>${M.fmt(s.duration)}s</small></button>`).join('')}</div></details>`;}
